/* =========================================================================
   3. STATE + LOCAL STORAGE
   ========================================================================= */

const LS_KEYS = {

  extraDraws: 'xskt_extra_draws',

  predictions: 'xskt_predictions',

  province: 'xskt_selected_province',

  windowSize: 'xskt_window_size'

};


let SEED_DRAWS = [];

let EXTRA_DRAWS =
  loadJSON(LS_KEYS.extraDraws, []);

let PREDICTIONS =
  loadJSON(LS_KEYS.predictions, []);

let SELECTED_PROVINCE =
  localStorage.getItem(
    LS_KEYS.province
  ) || 'tp-hcm';

let WINDOW_SIZE =
  parseInt(
    localStorage.getItem(
      LS_KEYS.windowSize
    ) || '30',
    10
  );

let LAST_FORECAST = null;


function loadJSON(key, fallback) {

  try {

    const raw =
      localStorage.getItem(key);

    return raw
      ? JSON.parse(raw)
      : fallback;

  } catch (e) {

    return fallback;

  }

}


function saveJSON(key, value) {

  try {

    localStorage.setItem(
      key,
      JSON.stringify(value)
    );

  } catch (e) {

    console.warn(
      'Không lưu được localStorage:',
      e
    );

  }

}


/* =========================================================================
   4. TIỆN ÍCH
   ========================================================================= */

function pad2(n) {

  return String(n)
    .padStart(2, '0');

}


function clamp(v, min = 0, max = 1) {

  return Math.max(
    min,
    Math.min(max, v)
  );

}


function safeDiv(a, b) {

  if (!b) return 0;

  return a / b;

}


function mean(arr) {

  if (!arr.length) return 0;

  return arr.reduce(
    (a, b) => a + b,
    0
  ) / arr.length;

}


function stdDev(arr) {

  if (arr.length < 2)
    return 0;

  const avg = mean(arr);

  const variance =
    mean(
      arr.map(
        v => Math.pow(v - avg, 2)
      )
    );

  return Math.sqrt(variance);

}


function numbersOfPrize(draw, key) {

  if (
    !draw ||
    !draw.prizes
  ) return [];

  const v =
    draw.prizes[key];

  if (v == null)
    return [];

  return Array.isArray(v)
    ? v
    : [v];

}


function loOfPrize(draw, key) {

  return numbersOfPrize(
    draw,
    key
  )
    .map(v => String(v))
    .filter(v => v.length >= 2)
    .map(v => v.slice(-2));

}


function loOfDraw(draw) {

  const out = [];

  PRIZE_META.forEach(pm => {

    loOfPrize(
      draw,
      pm.key
    ).forEach(
      n => out.push(n)
    );

  });

  return out;

}


function dedupeKey(draw) {

  return (
    draw.province +
    '|' +
    draw.date
  );

}


function getAllDrawsForProvince(slug) {

  const map =
    new Map();


  SEED_DRAWS
    .filter(
      d => d.province === slug
    )
    .forEach(
      d => map.set(
        dedupeKey(d),
        d
      )
    );


  EXTRA_DRAWS
    .filter(
      d => d.province === slug
    )
    .forEach(
      d => map.set(
        dedupeKey(d),
        d
      )
    );


  return Array
    .from(map.values())
    .sort(
      (a, b) =>
        b.date.localeCompare(
          a.date
        )
    );

}


function countDrawsPerProvince() {

  const out = {};

  PROVINCES.forEach(
    p => {

      out[p.slug] =
        getAllDrawsForProvince(
          p.slug
        ).length;

    }
  );

  return out;

}


function windowedDraws(
  draws,
  size
) {

  return draws.slice(
    0,
    Math.min(
      size,
      draws.length
    )
  );

}


/* =========================================================================
   5. FREQUENCY
   ========================================================================= */

function freqTable(values) {

  const table = {};

  for (
    let i = 0;
    i < 100;
    i++
  ) {

    table[pad2(i)] = 0;

  }


  values.forEach(v => {

    if (
      table[v] !== undefined
    ) {

      table[v]++;

    }

  });


  return table;

}


/* =========================================================================
   6. GAN
   ========================================================================= */

function ganTable(
  draws,
  getValues
) {

  const gan = {};

  for (
    let i = 0;
    i < 100;
    i++
  ) {

    gan[pad2(i)] =
      draws.length;

  }


  const found =
    new Set();


  draws.forEach(
    (draw, index) => {

      getValues(draw)
        .forEach(v => {

          if (
            !found.has(v)
          ) {

            found.add(v);

            gan[v] =
              index;

          }

        });

    }
  );


  return gan;

}


/* =========================================================================
   7. HEAD / TAIL
   ========================================================================= */

function headTailFreq(values) {

  const head =
    new Array(10).fill(0);

  const tail =
    new Array(10).fill(0);


  values.forEach(v => {

    if (
      typeof v !== 'string' ||
      v.length !== 2
    ) return;

    head[
      Number(v[0])
    ]++;

    tail[
      Number(v[1])
    ]++;

  });


  return {
    head,
    tail
  };

}


/* =========================================================================
   8. NORMALIZATION
   ========================================================================= */

function minMaxNormalize(obj) {

  const values =
    Object.values(obj);

  if (!values.length)
    return {};


  const min =
    Math.min(...values);

  const max =
    Math.max(...values);

  const range =
    max - min;


  const out = {};


  Object.keys(obj)
    .forEach(k => {

      out[k] =
        range === 0
          ? 0.5
          : (obj[k] - min) /
            range;

    });


  return out;

}


/* =========================================================================
   9. V2 CONFIG
   ========================================================================= */

/*
   Tổng trọng số = 1.00

   frequency  : 25%
   recent     : 18%
   momentum   : 12%
   gan        : 15%
   cycle      : 12%
   headTail   : 8%
   stability  : 10%
*/

const V2_WEIGHTS = {

  frequency: 0.25,

  recent: 0.18,

  momentum: 0.12,

  gan: 0.15,

  cycle: 0.12,

  headTail: 0.08,

  stability: 0.10

};


const MULTI_WINDOWS = [
  10,
  20,
  30,
  60
];


/* =========================================================================
   10. MULTI WINDOW FREQUENCY
   ========================================================================= */

function frequencyForWindow(
  draws,
  giaiKey,
  size
) {

  const win =
    windowedDraws(
      draws,
      size
    );

  const values = [];

  win.forEach(d => {

    loOfPrize(
      d,
      giaiKey
    ).forEach(
      n => values.push(n)
    );

  });


  return {

    window: win.length,

    values,

    freq:
      freqTable(values)

  };

}


function multiWindowFrequency(
  draws,
  giaiKey
) {

  const result = {};

  MULTI_WINDOWS.forEach(
    w => {

      result[w] =
        frequencyForWindow(
          draws,
          giaiKey,
          w
        );

    }
  );

  return result;

}


/* =========================================================================
   11. RECENCY SCORE
   ========================================================================= */

function calculateRecencyScores(
  draws,
  giaiKey,
  maxWindow = 30
) {

  const win =
    windowedDraws(
      draws,
      maxWindow
    );

  const scores = {};

  for (
    let i = 0;
    i < 100;
    i++
  ) {

    scores[pad2(i)] = 0;

  }


  win.forEach(
    (draw, index) => {

      /*
       * Kỳ càng gần hiện tại
       * trọng số càng lớn.
       */

      const weight =
        Math.exp(
          -index / 10
        );


      loOfPrize(
        draw,
        giaiKey
      ).forEach(n => {

        scores[n] +=
          weight;

      });

    }
  );


  return minMaxNormalize(
    scores
  );

}


/* =========================================================================
   12. MOMENTUM
   ========================================================================= */

function calculateMomentumScores(
  draws,
  giaiKey
) {

  const recent =
    frequencyForWindow(
      draws,
      giaiKey,
      10
    );

  const medium =
    frequencyForWindow(
      draws,
      giaiKey,
      30
    );


  const raw = {};


  const pm =
    prizeMetaOf(giaiKey);

  const countPerDraw =
    pm
      ? pm.count
      : 1;


  for (
    let i = 0;
    i < 100;
    i++
  ) {

    const n =
      pad2(i);


    const recentRate =
      safeDiv(
        recent.freq[n],
        Math.max(
          recent.window *
          countPerDraw,
          1
        )
      );


    const mediumRate =
      safeDiv(
        medium.freq[n],
        Math.max(
          medium.window *
          countPerDraw,
          1
        )
      );


    /*
     * >0 = đang tăng
     * <0 = đang giảm
     */

    raw[n] =
      recentRate -
      mediumRate;

  }


  return minMaxNormalize(
    raw
  );

}


/* =========================================================================
   13. CYCLE ANALYSIS
   ========================================================================= */

function occurrenceIndexes(
  draws,
  giaiKey,
  number
) {

  const indexes = [];

  draws.forEach(
    (draw, index) => {

      if (
        loOfPrize(
          draw,
          giaiKey
        ).includes(number)
      ) {

        indexes.push(index);

      }

    }
  );


  return indexes;

}


function calculateCycleScore(
  draws,
  giaiKey
) {

  const raw = {};


  for (
    let i = 0;
    i < 100;
    i++
  ) {

    const n =
      pad2(i);

    const indexes =
      occurrenceIndexes(
        draws,
        giaiKey,
        n
      );


    if (
      indexes.length < 2
    ) {

      raw[n] = 0;

      continue;

    }


    const gaps = [];

    for (
      let j = 0;
      j <
      indexes.length - 1;
      j++
    ) {

      gaps.push(
        indexes[j + 1] -
        indexes[j]
      );

    }


    const avgGap =
      mean(gaps);


    const currentGap =
      indexes[0];


    /*
     * Điểm cao khi khoảng gan hiện tại
     * tiến gần chu kỳ lịch sử trung bình.
     *
     * Không coi "quá gan" là chắc chắn
     * phải xuất hiện.
     */

    if (
      avgGap <= 0
    ) {

      raw[n] = 0;

      continue;

    }


    const ratio =
      currentGap /
      avgGap;


    /*
     * peak quanh ratio = 1
     */

    raw[n] =
      Math.exp(
        -Math.abs(
          ratio - 1
        )
      );

  }


  return minMaxNormalize(
    raw
  );

}


/* =========================================================================
   14. STABILITY
   ========================================================================= */

function calculateStabilityScore(
  draws,
  giaiKey
) {

  const segments = [
    [0, 10],
    [10, 20],
    [20, 30]
  ];


  const raw = {};


  for (
    let i = 0;
    i < 100;
    i++
  ) {

    const n =
      pad2(i);

    const rates = [];


    segments.forEach(
      ([start, end]) => {

        const segment =
          draws.slice(
            start,
            Math.min(
              end,
              draws.length
            )
          );


        if (!segment.length) {

          rates.push(0);

          return;

        }


        let count = 0;


        segment.forEach(d => {

          count +=
            loOfPrize(
              d,
              giaiKey
            )
            .filter(
              x => x === n
            ).length;

        });


        rates.push(
          count /
          segment.length
        );

      }
    );


    const avg =
      mean(rates);

    const sd =
      stdDev(rates);


    /*
     * Có xuất hiện đều ở nhiều đoạn
     * sẽ có stability cao hơn.
     */

    raw[n] =
      avg > 0
        ? avg /
          (1 + sd)
        : 0;

  }


  return minMaxNormalize(
    raw
  );

}


/* =========================================================================
   15. GAN SCORE V2
   ========================================================================= */

function calculateGanScore(
  draws,
  giaiKey
) {

  const gan =
    ganTable(
      draws,
      d =>
        loOfPrize(
          d,
          giaiKey
        )
    );


  /*
   * Không tăng điểm tuyến tính vô hạn.
   *
   * Sử dụng hàm saturation:
   *
   * gan/(gan+10)
   *
   * tránh suy luận:
   * "càng lâu chưa về càng chắc về".
   */

  const raw = {};


  for (
    let i = 0;
    i < 100;
    i++
  ) {

    const n =
      pad2(i);

    const g =
      gan[n];

    raw[n] =
      g /
      (g + 10);

  }


  return {

    raw: gan,

    normalized:
      minMaxNormalize(raw)

  };

}


/* =========================================================================
   16. HEAD / TAIL SCORE V2
   ========================================================================= */

function calculateHeadTailScore(
  draws,
  giaiKey,
  size = 30
) {

  const win =
    windowedDraws(
      draws,
      size
    );

  const values = [];


  win.forEach(d => {

    loOfPrize(
      d,
      giaiKey
    ).forEach(
      n => values.push(n)
    );

  });


  const {
    head,
    tail
  } =
    headTailFreq(values);


  const headMax =
    Math.max(
      ...head,
      1
    );

  const tailMax =
    Math.max(
      ...tail,
      1
    );


  const score = {};


  for (
    let i = 0;
    i < 100;
    i++
  ) {

    const n =
      pad2(i);

    score[n] =
      (
        head[
          Number(n[0])
        ] /
        headMax +

        tail[
          Number(n[1])
        ] /
        tailMax
      ) / 2;

  }


  return score;

}


/* =========================================================================
   17. FREQUENCY SCORE V2
   ========================================================================= */

function calculateMultiFrequencyScore(
  draws,
  giaiKey
) {

  const multi =
    multiWindowFrequency(
      draws,
      giaiKey
    );


  const raw = {};


  const windowWeights = {

    10: 0.40,

    20: 0.30,

    30: 0.20,

    60: 0.10

  };


  for (
    let i = 0;
    i < 100;
    i++
  ) {

    const n =
      pad2(i);

    let score = 0;


    MULTI_WINDOWS.forEach(
      w => {

        const data =
          multi[w];

        const total =
          Math.max(
            data.values.length,
            1
          );

        const rate =
          data.freq[n] /
          total;

        score +=
          rate *
          windowWeights[w];

      }
    );


    raw[n] =
      score;

  }


  return {

    raw,

    normalized:
      minMaxNormalize(raw),

    multi

  };

}


/* =========================================================================
   18. V2 SCORING ENGINE
   ========================================================================= */

function computeScoresForGiai(
  allDraws,
  giaiKey,
  windowSize
) {

  const pm =
    prizeMetaOf(giaiKey);


  const primaryWindow =
    windowedDraws(
      allDraws,
      windowSize
    );


  const flatValues = [];


  primaryWindow
    .forEach(d => {

      loOfPrize(
        d,
        giaiKey
      ).forEach(
        n =>
          flatValues.push(n)
      );

    });


  const freq =
    freqTable(
      flatValues
    );


  const expectedPerNumber =
    Math.max(
      primaryWindow.length *
      (pm ? pm.count : 1) /
      100,
      0.01
    );


  const frequency =
    calculateMultiFrequencyScore(
      allDraws,
      giaiKey
    );


  const recent =
    calculateRecencyScores(
      allDraws,
      giaiKey,
      Math.max(
        30,
        windowSize
      )
    );


  const momentum =
    calculateMomentumScores(
      allDraws,
      giaiKey
    );


  const ganResult =
    calculateGanScore(
      allDraws,
      giaiKey
    );


  const cycle =
    calculateCycleScore(
      allDraws,
      giaiKey
    );


  const headTail =
    calculateHeadTailScore(
      allDraws,
      giaiKey,
      windowSize
    );


  const stability =
    calculateStabilityScore(
      allDraws,
      giaiKey
    );


  const scores = {};


  const components = {};


  for (
    let i = 0;
    i < 100;
    i++
  ) {

    const n =
      pad2(i);


    const parts = {

      frequency:
        frequency.normalized[n] || 0,

      recent:
        recent[n] || 0,

      momentum:
        momentum[n] || 0,

      gan:
        ganResult.normalized[n] || 0,

      cycle:
        cycle[n] || 0,

      headTail:
        headTail[n] || 0,

      stability:
        stability[n] || 0

    };


    const finalScore =

      parts.frequency *
      V2_WEIGHTS.frequency +

      parts.recent *
      V2_WEIGHTS.recent +

      parts.momentum *
      V2_WEIGHTS.momentum +

      parts.gan *
      V2_WEIGHTS.gan +

      parts.cycle *
      V2_WEIGHTS.cycle +

      parts.headTail *
      V2_WEIGHTS.headTail +

      parts.stability *
      V2_WEIGHTS.stability;


    scores[n] =
      clamp(
        finalScore,
        0,
        1
      );


    components[n] =
      parts;

  }


  return {

    scores,

    components,

    freq,

    expectedPerNumber,

    gan:
      ganResult.raw,

    windowUsed:
      primaryWindow.length,

    multiFrequency:
      frequency.multi

  };

}


/* =========================================================================
   19. DETERMINISTIC RANKING
   ========================================================================= */

function rankedNumbers(scores) {

  return Object
    .entries(scores)
    .sort(
      (a, b) => {

        if (
          b[1] !== a[1]
        ) {

          return b[1] -
            a[1];

        }

        return a[0]
          .localeCompare(
            b[0]
          );

      }
    );

}


function deterministicPick(
  scores,
  count
) {

  return rankedNumbers(
    scores
  )
    .slice(
      0,
      count
    )
    .map(
      ([n]) => n
    );

}


/*
 * Giữ tên function cũ để tương thích
 * nếu HTML hoặc code khác đang gọi.
 *
 * V2 không còn roulette ngẫu nhiên.
 */

function weightedPickWithoutReplacement(
  scores,
  k
) {

  return deterministicPick(
    scores,
    k
  );

}


function rankOf(
  scores,
  number
) {

  const ranked =
    rankedNumbers(
      scores
    )
    .map(
      ([n]) => n
    );


  const index =
    ranked.indexOf(
      number
    );


  return index >= 0
    ? index + 1
    : 100;

}


/* =========================================================================
   20. CONFIDENCE
   ========================================================================= */

function confidenceOf(
  stat,
  number
) {

  const score =
    stat.scores[number] || 0;

  const components =
    stat.components[number] || {};


  const values =
    Object.values(
      components
    );


  /*
   * Agreement:
   * các tín hiệu càng đồng thuận
   * confidence càng cao.
   */

  const agreement =
    values.length
      ? clamp(
          1 -
          stdDev(values)
        )
      : 0;


  /*
   * Confidence không phải
   * xác suất trúng.
   */

  const confidence =
    (
      score * 0.70 +
      agreement * 0.30
    ) * 100;


  return Math.round(
    clamp(
      confidence,
      1,
      99
    )
  );

}


/* =========================================================================
   21. REASONING V2
   ========================================================================= */

function buildReasoning(
  number,
  giaiLabel,
  stat,
  windowSize
) {

  const freq =
    stat.freq[number] || 0;

  const gan =
    stat.gan[number] || 0;

  const rank =
    rankOf(
      stat.scores,
      number
    );

  const confidence =
    confidenceOf(
      stat,
      number
    );

  const c =
    stat.components[number];


  const signals = [];


  if (
    c.frequency >= 0.65
  ) {

    signals.push(
      'tần suất đa khung cao'
    );

  }


  if (
    c.recent >= 0.65
  ) {

    signals.push(
      'xu hướng gần đây tích cực'
    );

  }


  if (
    c.momentum >= 0.65
  ) {

    signals.push(
      'momentum đang tăng'
    );

  }


  if (
    c.cycle >= 0.65
  ) {

    signals.push(
      'đang gần chu kỳ xuất hiện lịch sử'
    );

  }


  if (
    c.headTail >= 0.65
  ) {

    signals.push(
      'đầu/đuôi đang có tín hiệu tốt'
    );

  }


  if (
    c.stability >= 0.65
  ) {

    signals.push(
      'tần suất tương đối ổn định'
    );

  }


  if (
    gan >= 5
  ) {

    signals.push(
      `đã gan ${gan} kỳ`
    );

  }


  if (
    !signals.length
  ) {

    signals.push(
      'điểm tổng hợp cao hơn phần lớn các số còn lại'
    );

  }


  return `
    Số <b>${number}</b> ·
    hạng <b>${rank}/100</b> ·
    điểm tin cậy mô hình
    <b>${confidence}/100</b>.
    Xuất hiện <b>${freq}</b> lần
    trong ${stat.windowUsed} kỳ
    gần nhất tại ${giaiLabel}.
    Tín hiệu chính:
    ${signals.join(', ')}.
  `;

}


const GLOBAL_DISCLAIMER_SHORT =
  'Điểm tin cậy là mức đồng thuận của mô hình thống kê, không phải xác suất trúng. Mỗi kỳ quay vẫn là sự kiện ngẫu nhiên độc lập.';


/* =========================================================================
   22. SỐ LƯỢNG GỢI Ý
   ========================================================================= */

function pickCountFor(
  giaiKey
) {

  if (
    ['db', 'g1', 'g2']
      .includes(giaiKey)
  ) {

    return 2;

  }


  return 3;

}


/* =========================================================================
   23. GENERATE FULL FORECAST V2
   ========================================================================= */

function generateFullForecast(
  provinceSlug,
  windowSize
) {

  const allDraws =
    getAllDrawsForProvince(
      provinceSlug
    );


  const result = {

    version: 'V2',

    province:
      provinceSlug,

    windowSize,

    generatedAt:
      new Date()
        .toISOString(),

    items: []

  };


  if (
    !allDraws.length
  ) {

    result.empty = true;

    return result;

  }


  PRIZE_META.forEach(
    pm => {

      const stat =
        computeScoresForGiai(
          allDraws,
          pm.key,
          windowSize
        );


      const k =
        pickCountFor(
          pm.key
        );


      const picks =
        deterministicPick(
          stat.scores,
          k
        );


      const numbers =
        picks.map(n => ({

          number: n,

          rank:
            rankOf(
              stat.scores,
              n
            ),

          score:
            stat.scores[n],

          confidence:
            confidenceOf(
              stat,
              n
            ),

          reasoning:
            buildReasoning(
              n,
              pm.label,
              stat,
              windowSize
            )

        }));


      result.items.push({

        key:
          pm.key,

        label:
          pm.label,

        numbers

      });

    }
  );


  return result;

}


/* =========================================================================
   24. CẦU GHÉP CẶP V2
   ========================================================================= */

function generatePairFormulas(
  provinceSlug,
  windowSize
) {

  const allDraws =
    getAllDrawsForProvince(
      provinceSlug
    );


  if (
    !allDraws.length
  ) return [];


  const win =
    windowedDraws(
      allDraws,
      windowSize
    );


  const allLoLists =
    win.map(
      d => loOfDraw(d)
    );


  const flat =
    allLoLists.flat();


  const freq =
    freqTable(flat);


  const gan =
    ganTable(
      allDraws,
      d => loOfDraw(d)
    );


  const {
    head,
    tail
  } =
    headTailFreq(flat);


  const out = [];


  /* -----------------------------------------------------------------------
     Công thức 1:
     Đầu mạnh + đuôi mạnh
     ----------------------------------------------------------------------- */

  const headRanked =
    head
      .map(
        (v, i) => [i, v]
      )
      .sort(
        (a, b) =>
          b[1] - a[1]
      );


  const tailRanked =
    tail
      .map(
        (v, i) => [i, v]
      )
      .sort(
        (a, b) =>
          b[1] - a[1]
      );


  if (
    headRanked.length &&
    tailRanked.length
  ) {

    const h =
      headRanked[0];

    const t =
      tailRanked[0];

    const number =
      `${h[0]}${t[0]}`;


    out.push({

      formula:
        'Đầu – Đuôi mạnh',

      pair:
        number,

      reasoning:
        `Đầu <b>${h[0]}</b> xuất hiện ${h[1]} lần và đuôi <b>${t[0]}</b> xuất hiện ${t[1]} lần trong ${win.length} kỳ gần nhất. Ghép thành <b>${number}</b>.`

    });

  }


  /* -----------------------------------------------------------------------
     Công thức 2:
     Co-occurrence
     ----------------------------------------------------------------------- */

  const coCount = {};


  allLoLists.forEach(
    list => {

      const uniq =
        Array.from(
          new Set(list)
        ).sort();


      for (
        let i = 0;
        i < uniq.length;
        i++
      ) {

        for (
          let j = i + 1;
          j < uniq.length;
          j++
        ) {

          const key =
            `${uniq[i]}-${uniq[j]}`;

          coCount[key] =
            (
              coCount[key] || 0
            ) + 1;

        }

      }

    }
  );


  const coRanked =
    Object.entries(
      coCount
    )
    .sort(
      (a, b) => {

        if (
          b[1] !== a[1]
        ) {

          return b[1] -
            a[1];

        }

        return a[0]
          .localeCompare(
            b[0]
          );

      }
    );


  if (
    coRanked.length
  ) {

    const [
      pair,
      count
    ] =
      coRanked[0];


    out.push({

      formula:
        'Song thủ đồng xuất hiện',

      pair,

      reasoning:
        `Cặp <b>${pair}</b> cùng xuất hiện trong <b>${count}</b> kỳ trên ${win.length} kỳ gần nhất, đứng đầu bảng đồng xuất hiện.`

    });

  }


  /* -----------------------------------------------------------------------
     Công thức 3:
     Nóng + gan
     ----------------------------------------------------------------------- */

  const hotRanked =
    Object.entries(
      freq
    )
    .sort(
      (a, b) => {

        if (
          b[1] !== a[1]
        ) {

          return b[1] -
            a[1];

        }

        return a[0]
          .localeCompare(
            b[0]
          );

      }
    );


  const ganRanked =
    Object.entries(
      gan
    )
    .sort(
      (a, b) => {

        if (
          b[1] !== a[1]
        ) {

          return b[1] -
            a[1];

        }

        return a[0]
          .localeCompare(
            b[0]
          );

      }
    );


  if (
    hotRanked.length &&
    ganRanked.length
  ) {

    const hot =
      hotRanked[0];

    const cold =
      ganRanked.find(
        x => x[0] !== hot[0]
      ) || ganRanked[0];


    out.push({

      formula:
        'Nóng – Gan',

      pair:
        `${hot[0]}-${cold[0]}`,

      reasoning:
        `Số <b>${hot[0]}</b> đang có tần suất cao (${hot[1]} lần/${win.length} kỳ), kết hợp số <b>${cold[0]}</b> đã gan ${cold[1]} kỳ. Đây là tín hiệu thống kê nóng–lạnh, không phải quy luật chắc chắn.`

    });

  }


  return out;

}


/* =========================================================================
   25. NGÀY QUAY TIẾP THEO
   ========================================================================= */

function isoDate(d) {

  return (
    d.getFullYear() +
    '-' +
    pad2(
      d.getMonth() + 1
    ) +
    '-' +
    pad2(
      d.getDate()
    )
  );

}


function nextDrawDateISO(
  provinceSlug,
  fromDate
) {

  const p =
    provinceBySlug(
      provinceSlug
    );


  if (!p)
    return null;


  const days =
    new Set(
      p.days.map(
        d => DAY_INDEX[d]
      )
    );


  const base =
    fromDate
      ? new Date(fromDate)
      : new Date();


  base.setHours(
    0,
    0,
    0,
    0
  );


  for (
    let offset = 0;
    offset <= 7;
    offset++
  ) {

    const d =
      new Date(base);

    d.setDate(
      base.getDate() +
      offset
    );


    if (
      days.has(
        d.getDay()
      )
    ) {

      return isoDate(d);

    }

  }


  return null;

}


/* =========================================================================
   26. SAVE PREDICTION
   ========================================================================= */

function savePrediction(
  forecast,
  pairFormulas
) {

  const targetDate =
    nextDrawDateISO(
      forecast.province,
      new Date()
    );


  const record = {

    id:
      'p' +
      Date.now() +
      Math.floor(
        Math.random() * 1000
      ),

    version:
      forecast.version ||
      'V2',

    province:
      forecast.province,

    savedAt:
      new Date()
        .toISOString(),

    targetDate,

    windowSize:
      forecast.windowSize,

    items:
      forecast.items.map(
        item => ({

          key:
            item.key,

          label:
            item.label,

          numbers:
            item.numbers.map(
              n => n.number
            )

        })
      ),

    pairFormulas:
      (pairFormulas || [])
        .map(p => ({

          formula:
            p.formula,

          pair:
            p.pair

        }))

  };


  PREDICTIONS.unshift(
    record
  );


  saveJSON(
    LS_KEYS.predictions,
    PREDICTIONS
  );


  return record;

}


/* =========================================================================
   27. SO SÁNH DỰ BÁO
   ========================================================================= */

function findActualDraw(
  provinceSlug,
  dateISO
) {

  return (
    getAllDrawsForProvince(
      provinceSlug
    )
    .find(
      d =>
        d.date === dateISO
    ) || null
  );

}


function evaluatePrediction(
  pred
) {

  const actual =
    findActualDraw(
      pred.province,
      pred.targetDate
    );


  if (!actual) {

    return {

      status:
        'pending',

      actual:
        null,

      hits: [],

      totalMatched:
        0

    };

  }


  const hits = [];


  pred.items.forEach(
    item => {

      const actualLo =
        loOfPrize(
          actual,
          item.key
        );


      const matched =
        item.numbers.filter(
          n =>
            actualLo.includes(n)
        );


      hits.push({

        key:
          item.key,

        label:
          item.label,

        predicted:
          item.numbers,

        actual:
          actualLo,

        matched

      });

    }
  );


  const totalMatched =
    hits.reduce(
      (sum, h) =>
        sum +
        h.matched.length,
      0
    );


  return {

    status:
      totalMatched > 0
        ? 'win'
        : 'lose',

    actual,

    hits,

    totalMatched

  };

}


/* =========================================================================
   28. DEVIATION ANALYSIS
   ========================================================================= */

function buildDeviationNote(
  pred,
  evaluation
) {

  if (
    evaluation.status ===
    'pending'
  ) return '';


  const historical =
    getAllDrawsForProvince(
      pred.province
    )
    .filter(
      d =>
        d.date <
        pred.targetDate
    );


  const notes = [];


  evaluation.hits
    .forEach(h => {

      if (
        h.matched.length
      ) {

        notes.push(
          `${h.label}: dự báo đúng số <b>${h.matched.join(', ')}</b>.`
        );

        return;

      }


      if (
        !h.actual.length ||
        !historical.length
      ) return;


      const stat =
        computeScoresForGiai(
          historical,
          h.key,
          pred.windowSize || 30
        );


      const ranks =
        h.actual.map(
          n =>
            `${n} (hạng ${rankOf(stat.scores, n)}/100)`
        );


      notes.push(
        `${h.label}: thực tế ${ranks.join(', ')} — không nằm trong nhóm dự báo V2.`
      );

    });


  return notes.join(' ');

}


function deletePrediction(id) {

  PREDICTIONS =
    PREDICTIONS.filter(
      p => p.id !== id
    );


  saveJSON(
    LS_KEYS.predictions,
    PREDICTIONS
  );

}


/* =========================================================================
   29. PARSER DỮ LIỆU DÁN TAY
   ========================================================================= */

const PRIZE_REGEX = [

  {
    key: 'db',
    re: /Gi(ả|a)i\s*(Đ(ặ|a)c\s*Bi(ệ|e)t|ĐB)[^\d]{0,40}(\d{6})\b/i,
    digits: 6,
    group: 5
  },

  {
    key: 'g1',
    re: /Gi(ả|a)i\s*nh(ấ|a)t[^\d]{0,40}(\d{5})\b/i,
    digits: 5,
    group: 3
  },

  {
    key: 'g2',
    re: /Gi(ả|a)i\s*nh(ì|i)[^\d]{0,40}(\d{5})\b/i,
    digits: 5,
    group: 3
  },

  {
    key: 'g3',
    re: /Gi(ả|a)i\s*ba[^\d]{0,40}(\d{10})\b/i,
    digits: 10,
    group: 2,
    split: 5
  },

  {
    key: 'g4',
    re: /Gi(ả|a)i\s*t(ư|u)[^\d]{0,40}(\d{35})\b/i,
    digits: 35,
    group: 3,
    split: 5
  },

  {
    key: 'g5',
    re: /Gi(ả|a)i\s*n(ă|a)m[^\d]{0,40}(\d{4})\b/i,
    digits: 4,
    group: 3
  },

  {
    key: 'g6',
    re: /Gi(ả|a)i\s*s(á|a)u[^\d]{0,40}(\d{12})\b/i,
    digits: 12,
    group: 3,
    split: 4
  },

  {
    key: 'g7',
    re: /Gi(ả|a)i\s*b(ả|a)y[^\d]{0,40}(\d{3})\b/i,
    digits: 3,
    group: 3
  },

  {
    key: 'g8',
    re: /Gi(ả|a)i\s*(t(á|a)m|8)[^\d]{0,40}(\d{2})\b/i,
    digits: 2,
    group: 4
  }

];


function splitDigits(
  str,
  size
) {

  const out = [];

  for (
    let i = 0;
    i < str.length;
    i += size
  ) {

    out.push(
      str.slice(
        i,
        i + size
      )
    );

  }

  return out;

}


const DATE_RE =
  /(\d{2})\/(\d{2})\/(\d{4})/g;


function splitTextByDate(text) {

  const matches =
    [...text.matchAll(DATE_RE)];


  if (!matches.length)
    return [];


  const segments = [];


  for (
    let i = 0;
    i < matches.length;
    i++
  ) {

    const start =
      matches[i].index;

    const end =
      i + 1 <
      matches.length
        ? matches[i + 1].index
        : text.length;


    segments.push({

      dateStr:
        matches[i][0],

      text:
        text.slice(
          start,
          end
        )

    });

  }


  return segments;

}


function parseSegmentToDraw(
  segment,
  provinceSlug
) {

  const [
    dd,
    mm,
    yyyy
  ] =
    segment.dateStr
      .split('/');


  const dateISO =
    `${yyyy}-${mm}-${dd}`;


  const prizes = {};

  let foundCount = 0;


  for (
    const pr of
    PRIZE_REGEX
  ) {

    const match =
      segment.text.match(
        pr.re
      );


    if (!match)
      continue;


    const raw =
      match[pr.group];


    if (
      !raw ||
      raw.length !==
      pr.digits
    ) {

      continue;

    }


    prizes[pr.key] =
      pr.split
        ? splitDigits(
            raw,
            pr.split
          )
        : raw;


    foundCount++;

  }


  if (
    foundCount <
    PRIZE_REGEX.length
  ) {

    return null;

  }


  let ticketCode = '';


  const ticketMatch =
    segment.text.match(
      /Lo(ạ|a)i\s*v[ée]\s*[:：]?\s*([A-Z0-9]{2,8})/i
    );


  if (
    ticketMatch
  ) {

    ticketCode =
      ticketMatch[2];

  } else {

    const alt =
      segment.text.match(
        /XS[A-ZĐ]{2,5}\s*-\s*([A-Z0-9]{2,8})/i
      );

    if (alt) {

      ticketCode =
        alt[1];

    }

  }


  return {

    province:
      provinceSlug,

    date:
      dateISO,

    ticketCode,

    prizes

  };

}


function parseDrawsFromText(
  text,
  provinceSlug
) {

  const segments =
    splitTextByDate(text);


  const draws = [];

  let skipped = 0;


  segments.forEach(
    segment => {

      const draw =
        parseSegmentToDraw(
          segment,
          provinceSlug
        );


      if (draw) {

        draws.push(draw);

      } else {

        skipped++;

      }

    }
  );


  return {

    draws,

    skipped,

    totalSegments:
      segments.length

  };

}


/* =========================================================================
   30. MERGE DATA
   ========================================================================= */

function mergeExtraDraws(
  newDraws
) {

  const map =
    new Map();


  EXTRA_DRAWS
    .forEach(
      d =>
        map.set(
          dedupeKey(d),
          d
        )
    );


  let added = 0;

  let updated = 0;


  newDraws.forEach(
    draw => {

      const key =
        dedupeKey(draw);


      if (
        map.has(key)
      ) {

        updated++;

      } else {

        added++;

      }


      map.set(
        key,
        draw
      );

    }
  );


  EXTRA_DRAWS =
    Array.from(
      map.values()
    );


  saveJSON(
    LS_KEYS.extraDraws,
    EXTRA_DRAWS
  );


  return {

    added,

    updated

  };

}


/* =========================================================================
   31. GITHUB JSON
   ========================================================================= */

async function fetchProvinceLive(
  slug
) {

  try {

    const url =
      `data/${slug}-latest.json?t=${Date.now()}`;


    const response =
      await fetch(
        url,
        {
          cache:
            'no-store'
        }
      );


    if (
      !response.ok
    ) {

      throw new Error(
        `HTTP ${response.status}`
      );

    }


    const json =
      await response.json();


    if (
      !json ||
      !json.results
    ) {

      throw new Error(
        'File JSON không có results'
      );

    }


    if (
      !json.drawDate
    ) {

      throw new Error(
        'File JSON chưa có drawDate'
      );

    }


    const r =
      json.results;


    const draw = {

      province:
        slug,

      date:
        json.drawDate,

      ticketCode:
        '',

      prizes: {

        db:
          Array.isArray(
            r.giaidb
          )
            ? String(
                r.giaidb[0] || ''
              )
            : '',


        g1:
          Array.isArray(
            r.giai1
          )
            ? String(
                r.giai1[0] || ''
              )
            : '',


        g2:
          Array.isArray(
            r.giai2
          )
            ? String(
                r.giai2[0] || ''
              )
            : '',


        g3:
          Array.isArray(
            r.giai3
          )
            ? r.giai3.map(String)
            : [],


        g4:
          Array.isArray(
            r.giai4
          )
            ? r.giai4.map(String)
            : [],


        g5:
          Array.isArray(
            r.giai5
          )
            ? String(
                r.giai5[0] || ''
              )
            : '',


        g6:
          Array.isArray(
            r.giai6
          )
            ? r.giai6.map(String)
            : [],


        g7:
          Array.isArray(
            r.giai7
          )
            ? String(
                r.giai7[0] || ''
              )
            : '',


        g8:
          Array.isArray(
            r.giai8
          )
            ? String(
                r.giai8[0] || ''
              )
            : ''

      }

    };


    const valid =

      /^\d{6}$/
        .test(
          draw.prizes.db
        ) &&

      /^\d{5}$/
        .test(
          draw.prizes.g1
        ) &&

      /^\d{5}$/
        .test(
          draw.prizes.g2
        ) &&

      draw.prizes.g3
        .length === 2 &&

      draw.prizes.g3
        .every(
          v =>
            /^\d{5}$/
              .test(v)
        ) &&

      draw.prizes.g4
        .length === 7 &&

      draw.prizes.g4
        .every(
          v =>
            /^\d{5}$/
              .test(v)
        ) &&

      /^\d{4}$/
        .test(
          draw.prizes.g5
        ) &&

      draw.prizes.g6
        .length === 3 &&

      draw.prizes.g6
        .every(
          v =>
            /^\d{4}$/
              .test(v)
        ) &&

      /^\d{3}$/
        .test(
          draw.prizes.g7
        ) &&

      /^\d{2}$/
        .test(
          draw.prizes.g8
        );


    if (!valid) {

      throw new Error(
        'Dữ liệu kỳ quay không đầy đủ hoặc sai định dạng'
      );

    }


    const mergeResult =
      mergeExtraDraws(
        [draw]
      );


    return {

      ok: true,

      count: 1,

      skipped: 0,

      added:
        mergeResult.added,

      updated:
        mergeResult.updated,

      drawDate:
        json.drawDate,

      updatedAt:
        json.updatedAt ||
        null

    };


  } catch (e) {

    console.error(
      `Không tải được dữ liệu ${slug}:`,
      e
    );


    return {

      ok: false,

      error:
        e.message ||
        String(e)

    };

  }

}


/* =========================================================================
   32. PROVINCE SELECT
   ========================================================================= */

function populateProvinceSelects() {

  const grouped = {};


  PROVINCES.forEach(
    p => {

      const dayKey =
        p.days.join(', ');


      if (
        !grouped[dayKey]
      ) {

        grouped[dayKey] = [];

      }


      grouped[dayKey]
        .push(p);

    }
  );


  const buildOptions =
    () => {

      let html = '';


      Object.keys(
        grouped
      )
      .forEach(
        dayKey => {

          html +=
            `<optgroup label="${dayKey}">`;


          grouped[dayKey]
            .forEach(p => {

              html +=
                `<option value="${p.slug}">${p.name}</option>`;

            });


          html +=
            '</optgroup>';

        }
      );


      return html;

    };


  const sel1 =
    document.getElementById(
      'provinceSelect'
    );


  const sel2 =
    document.getElementById(
      'pasteProvinceSelect'
    );


  if (sel1) {

    sel1.innerHTML =
      buildOptions();

    sel1.value =
      SELECTED_PROVINCE;

  }


  if (sel2) {

    sel2.innerHTML =
      buildOptions();

    sel2.value =
      SELECTED_PROVINCE;

  }

}


