/* =========================================================================
   38. RENDER FORECAST V2
   ========================================================================= */

function renderForecast() {

  const p =
    provinceBySlug(
      SELECTED_PROVINCE
    );


  const forecast =
    generateFullForecast(
      SELECTED_PROVINCE,
      WINDOW_SIZE
    );


  const container =
    document.getElementById(
      'forecastResults'
    );


  if (!container)
    return;


  if (
    forecast.empty
  ) {

    container.innerHTML =
      `
      <div class="card">
        <div class="empty-state">
          Chưa có dữ liệu lịch sử cho ${p ? p.name : SELECTED_PROVINCE}.
          <br>
          Vào tab Cài đặt để cập nhật dữ liệu.
        </div>
      </div>
      `;


    const pairCard =
      document
        .getElementById(
          'pairFormulaCard'
        );


    if (pairCard) {

      pairCard.style.display =
        'none';

    }


    LAST_FORECAST =
      null;

    return;

  }


  let html =
    `
    <div class="card">
      <div style="font-weight:800;margin-bottom:5px;">
        🧠 Statistical Engine V2
      </div>

      <div class="sub">
        Multi-window · Frequency · Recent Trend · Momentum · Gan · Cycle · Head/Tail · Stability
      </div>

      <div class="sub" style="margin-top:6px;">
        ${GLOBAL_DISCLAIMER_SHORT}
      </div>
    </div>
    `;


  forecast.items
    .forEach(
      item => {

        html +=
          `
          <div class="prize-card">

            <div class="prize-head">

              <span class="prize-name">
                ${item.label}
              </span>

              <span class="prize-tag">
                ${p ? p.name : ''}
              </span>

            </div>


            <div class="num-chip-row">

              ${item.numbers
                .map(
                  n =>
                    `<span class="num-chip"
                      title="Hạng ${n.rank}/100 · Confidence ${n.confidence}/100">
                      ${n.number}
                    </span>`
                )
                .join('')}

            </div>


            ${item.numbers
              .map(
                n =>
                  `
                  <div class="reasoning">

                    ${n.reasoning}

                  </div>
                  `
              )
              .join('')}

          </div>
          `;

      }
    );


  container.innerHTML =
    html;


  const pairFormulas =
    generatePairFormulas(
      SELECTED_PROVINCE,
      WINDOW_SIZE
    );


  const pairCard =
    document.getElementById(
      'pairFormulaCard'
    );


  const pairResults =
    document.getElementById(
      'pairFormulaResults'
    );


  if (
    pairCard &&
    pairResults &&
    pairFormulas.length
  ) {

    pairCard.style.display =
      '';


    pairResults.innerHTML =
      pairFormulas
        .map(
          pf =>
            `
            <div class="pair-card">

              <div class="pair-formula">
                ${pf.formula}
              </div>

              <div class="pair-nums">
                ${pf.pair}
              </div>

              <div class="pair-reason">
                ${pf.reasoning}
              </div>

            </div>
            `
        )
        .join('');

  } else if (
    pairCard
  ) {

    pairCard.style.display =
      'none';

  }


  LAST_FORECAST = {

    forecast,

    pairFormulas

  };

}


