/* =========================================================================
   40. RENDER STATS
   ========================================================================= */

function renderStatsTab() {

  const p =
    provinceBySlug(
      SELECTED_PROVINCE
    );


  const name =
    document.getElementById(
      'statProvinceName'
    );


  if (name) {

    name.textContent =
      p ? p.name : '';

  }


  const allDraws =
    getAllDrawsForProvince(
      SELECTED_PROVINCE
    );


  const win =
    windowedDraws(
      allDraws,
      WINDOW_SIZE
    );


  const history =
    document.getElementById(
      'historyList'
    );


  if (history) {

    if (
      !win.length
    ) {

      history.innerHTML =
        '<div class="empty-state">Chưa có dữ liệu.</div>';

    } else {

      history.innerHTML =
        win.map(
          d =>
            `
            <div class="history-row">

              <div>

                <div class="hd">
                  ${d.date}${d.ticketCode ? ' · ' + d.ticketCode : ''}
                </div>

                <div class="history-lo">
                  Lô: ${loOfDraw(d).join(' ')}
                </div>

              </div>

              <div class="hdb">
                ${d.prizes.db}
              </div>

            </div>
            `
        )
        .join('');

    }

  }


  if (
    !win.length
  ) {

    const table =
      document.getElementById(
        'headTailTable'
      );

    const ganList =
      document.getElementById(
        'ganList'
      );

    const hotList =
      document.getElementById(
        'hotList'
      );


    if (table)
      table.innerHTML = '';

    if (ganList)
      ganList.innerHTML =
        '<div class="empty-state">--</div>';

    if (hotList)
      hotList.innerHTML =
        '<div class="empty-state">--</div>';

    return;

  }


  const flat =
    win
      .map(
        d => loOfDraw(d)
      )
      .flat();


  const freq =
    freqTable(flat);


  const byNumber = {};


  flat.forEach(
    v => {

      byNumber[v] =
        (
          byNumber[v] ||
          0
        ) + 1;

    }
  );


  let tableHtml =
    '<tr><th>Chục\\Đơn vị</th>' +
    [...Array(10).keys()]
      .map(
        i => `<th>${i}</th>`
      )
      .join('') +
    '</tr>';


  for (
    let h = 0;
    h < 10;
    h++
  ) {

    tableHtml +=
      `<tr><th>${h}</th>`;


    for (
      let t = 0;
      t < 10;
      t++
    ) {

      const n =
        `${h}${t}`;

      const count =
        byNumber[n] || 0;


      tableHtml +=
        `
        <td style="${
          count > 0
            ? 'color:var(--accent);font-weight:800;'
            : 'color:var(--text-dim);'
        }">
          ${count || '·'}
        </td>
        `;

    }


    tableHtml +=
      '</tr>';

  }


  const table =
    document.getElementById(
      'headTailTable'
    );


  if (table) {

    table.innerHTML =
      tableHtml;

  }


  const ganFull =
    ganTable(
      allDraws,
      d => loOfDraw(d)
    );


  const ganRanked =
    Object.entries(
      ganFull
    )
    .sort(
      (a, b) =>
        b[1] - a[1]
    )
    .slice(
      0,
      10
    );


  const ganList =
    document.getElementById(
      'ganList'
    );


  if (ganList) {

    ganList.innerHTML =
      ganRanked
        .map(
          ([n, g]) =>
            `
            <div class="history-row">

              <span class="hdb" style="font-size:16px;">
                ${n}
              </span>

              <span class="badge cold">
                Gan ${g} kỳ
              </span>

            </div>
            `
        )
        .join('');

  }


  const hotRanked =
    Object.entries(
      freq
    )
    .sort(
      (a, b) =>
        b[1] - a[1]
    )
    .slice(
      0,
      10
    );


  const hotList =
    document.getElementById(
      'hotList'
    );


  if (hotList) {

    hotList.innerHTML =
      hotRanked
        .map(
          ([n, f]) =>
            `
            <div class="history-row">

              <span class="hdb" style="font-size:16px;">
                ${n}
              </span>

              <span class="badge hot">
                ${f} lần / ${win.length} kỳ
              </span>

            </div>
            `
        )
        .join('');

  }

}


/* =========================================================================
   41. RENDER COMPARE
   ========================================================================= */

function renderCompareTab() {

  const list =
    document.getElementById(
      'predictionList'
    );


  const summary =
    document.getElementById(
      'compareSummary'
    );


  if (
    !list ||
    !summary
  ) return;


  if (
    !PREDICTIONS.length
  ) {

    list.innerHTML =
      `
      <div class="card">
        <div class="empty-state">
          Chưa có dự báo nào được lưu.
          Sang tab Dự Báo → Dự Báo Ngay → Lưu dự báo này.
        </div>
      </div>
      `;


    summary.innerHTML =
      '';

    return;

  }


  let winCount = 0;

  let loseCount = 0;

  let pendingCount = 0;

  let html = '';


  PREDICTIONS.forEach(
    pred => {

      const ev =
        evaluatePrediction(
          pred
        );


      if (
        ev.status === 'win'
      ) {

        winCount++;

      } else if (
        ev.status === 'lose'
      ) {

        loseCount++;

      } else {

        pendingCount++;

      }


      const p =
        provinceBySlug(
          pred.province
        );


      const statusLabel =
        ev.status === 'win'

          ? `🎉 Trúng ${ev.totalMatched} số`

          : ev.status === 'lose'

            ? '✗ Chưa trúng'

            : '⏳ Chờ kết quả';


      const statusClass =
        ev.status === 'win'

          ? 'win'

          : ev.status === 'lose'

            ? 'lose'

            : 'pending';


      let detail = '';


      if (
        ev.status !==
        'pending'
      ) {

        const note =
          buildDeviationNote(
            pred,
            ev
          );


        detail =
          `<div class="pred-detail">${note}</div>`;

      }


      html +=
        `
        <div class="pred-item">

          <div class="pred-top">

            <div>

              <div class="pred-title">
                ${p ? p.name : pred.province}
                ${pred.version ? ' · ' + pred.version : ''}
              </div>

              <div class="pred-date">
                Kỳ dự kiến: ${pred.targetDate}
                · Lưu lúc
                ${new Date(pred.savedAt).toLocaleString('vi-VN')}
              </div>

            </div>

            <span class="pred-status ${statusClass}">
              ${statusLabel}
            </span>

          </div>

          ${detail}

          <div class="btn-row">

            <button
              class="btn-danger"
              data-del="${pred.id}">
              Xoá
            </button>

          </div>

        </div>
        `;

    }
  );


  list.innerHTML =
    html;


  const total =
    PREDICTIONS.length;


  const evaluated =
    winCount +
    loseCount;


  const rate =
    evaluated
      ? Math.round(
          winCount /
          evaluated *
          100
        )
      : 0;


  summary.innerHTML =
    `
    <div class="data-count-grid">

      <div>
        <span class="n">${total}</span>
        Tổng dự báo
      </div>

      <div>
        <span class="n">${winCount}</span>
        Trúng ≥1 số
      </div>

      <div>
        <span class="n">${pendingCount}</span>
        Đang chờ
      </div>

    </div>

    ${
      evaluated
        ? `
          <p class="sub" style="margin-top:10px;">
            Backtest thực tế:
            <b style="color:var(--accent)">
              ${rate}%
            </b>
            số dự báo đã đánh giá có ít nhất một số trùng kết quả.
            Chỉ số này dùng để theo dõi hiệu quả mô hình,
            không phải xác suất trúng giải.
          </p>
          `
        : ''
    }
    `;


  list
    .querySelectorAll(
      '[data-del]'
    )
    .forEach(
      btn => {

        btn.addEventListener(
          'click',
          () => {

            deletePrediction(
              btn.dataset.del
            );

            renderCompareTab();

          }
        );

      }
    );

}


