/* =========================================================================
   35. RELIABILITY LABEL
   ========================================================================= */

function reliabilityIconV26(
  classification
) {

  switch (
    String(
      classification || ''
    )
  ) {

    case 'STRONG':
      return '🟢';

    case 'MODERATE':
      return '🟡';

    case 'WEAK':
      return '🟠';

    case 'FAIL':
      return '🔴';

    default:
      return '⚪';

  }

}


/* =========================================================================
   36. SIGNED NUMBER
   ========================================================================= */

function signedNumberV26(
  value,
  digits = 4
) {

  const n =
    Number(
      value || 0
    );


  return (
    n > 0
      ? '+'
      : ''
  ) +
  n.toFixed(
    digits
  );

}


/* =========================================================================
   37. PERCENT
   ========================================================================= */

function reliabilityPercentV26(
  value
) {

  return (
    Number(
      value || 0
    ) *
    100
  ).toFixed(2) + '%';

}


/* =========================================================================
   38. BUILD ONE RELIABILITY PERIOD
   ========================================================================= */

function buildReliabilityPeriodCardV26(
  row
) {

  const outcomeIcon =
    row.outcome === 'WIN'
      ? '🟢'
      : row.outcome === 'LOSS'
        ? '🔴'
        : '🟡';


  return `

    <div
      style="
        margin-top:14px;
        padding:15px;
        border-radius:15px;
        background:#f4f5f8;
        border:1px solid #dddddd;
      "
    >

      <div
        style="
          font-size:18px;
          font-weight:900;
          margin-bottom:10px;
        "
      >
        ${outcomeIcon}
        PERIOD ${row.period} — ${row.outcome}
      </div>


      <div>
        <b>Model:</b>
        ${row.model}
      </div>


      <div>
        <b>Window:</b>
        ${row.window} kỳ
      </div>


      <div>
        <b>Selection Quality:</b>
        ${row.selectionQuality.toFixed(2)}
      </div>


      <div>
        <b>Selection Margin:</b>
        ${row.selectionMargin.toFixed(4)}
      </div>


      <div>
        <b>Training Confidence:</b>
        ${row.selectionConfidence}
      </div>


      <div
        style="
          margin-top:9px;
          font-weight:800;
        "
      >
        OOS Delta:
        ${signedNumberV26(
          row.oosDelta,
          4
        )}
      </div>


      <div style="margin-top:9px;">
        <b>Fragile Selection:</b>
        ${
          row.fragileSelection
            ? '⚠️ YES'
            : 'NO'
        }
      </div>


      <div>
        <b>Overfit Signal:</b>
        ${
          row.overfitSignal
            ? '⚠️ YES'
            : 'NO'
        }
      </div>

    </div>

  `;

}


