/* =========================================================================
   53. PROGRESS BAR
   ========================================================================= */

function renderCrossOOSProgressV26(
  current,
  total,
  provinceName
) {

  const panel =
    getCrossOOSPanelV26();


  if (!panel) {

    return;

  }


  const percentage =
    total
      ? Math.round(
          current /
          total *
          100
        )
      : 0;


  panel.innerHTML = `

    <div
      style="
        font-size:20px;
        font-weight:900;
        margin-bottom:8px;
      "
    >
      🌐 V2.6 CROSS-PROVINCE OOS
    </div>


    <div
      style="
        margin-bottom:12px;
      "
    >
      Đang kiểm định:
      <b>
        ${provinceName || '...'}
      </b>
    </div>


    <div
      style="
        display:flex;
        justify-content:space-between;
        gap:10px;
        margin-bottom:7px;
        font-weight:800;
      "
    >

      <span>
        ${current}/${total}
      </span>

      <span>
        ${percentage}%
      </span>

    </div>


    <div
      style="
        width:100%;
        height:14px;
        border-radius:999px;
        overflow:hidden;
        background:rgba(255,255,255,.12);
      "
    >

      <div
        style="
          width:${percentage}%;
          height:100%;
          background:#ffc447;
          transition:width .2s ease;
        "
      >
      </div>

    </div>


    <div
      style="
        margin-top:12px;
        opacity:.75;
        font-size:13px;
      "
    >
      Không đóng trang trong khi
      quá trình kiểm định đang chạy.
    </div>

  `;

}


/* =========================================================================
   54. FORMAT DELTA
   ========================================================================= */

function crossOOSDeltaTextV26(
  value
) {

  const n =
    Number(
      value || 0
    );


  return (
    n > 0
      ? '+'
      : ''
  ) +
  n.toFixed(
    4
  );

}


/* =========================================================================
   55. CLASSIFICATION ICON
   ========================================================================= */

function crossOOSClassIconV26(
  classification
) {

  switch (
    classification
  ) {

    case 'PASS':
      return '🟢';

    case 'WEAK':
      return '🟡';

    case 'FAIL':
      return '🔴';

    case 'ERROR':
      return '❌';

    default:
      return '⚪';

  }

}


/* =========================================================================
   56. RUN ONE PROVINCE

   Có yield trước và sau calculation
   để browser có cơ hội cập nhật UI.
   ========================================================================= */

async function runOneCrossOOSV26(
  province,
  giaiKey
) {

  await crossOOSWaitV26(
    60
  );


  let result;


  try {

    result =
      evaluateCrossProvinceItemV26(
        province,
        giaiKey
      );

  } catch (error) {

    console.error(
      'V2.6 Mobile Batch:',
      province.slug,
      error
    );


    result = {

      ready: false,

      province:
        province.slug,

      provinceName:
        province.name,

      prize:
        giaiKey,

      classification:
        'ERROR',

      reason:
        String(
          error.message ||
          error
        )

    };

  }


  await crossOOSWaitV26(
    60
  );


  return result;

}


/* =========================================================================
   57. RUN BATCH

   Chạy tuần tự:
   Province 1 -> yield
   Province 2 -> yield
   ...
   Province 21.
   ========================================================================= */

async function runCrossProvinceBatchV26(
  giaiKey = 'db'
) {

  if (
    CROSS_OOS_BATCH_V26.running
  ) {

    alert(
      'V2.6 Cross-Province đang chạy.'
    );

    return null;

  }


  if (
    !Array.isArray(
      PROVINCES
    ) ||
    !PROVINCES.length
  ) {

    alert(
      'Không tìm thấy danh sách tỉnh.'
    );

    return null;

  }


  CROSS_OOS_BATCH_V26.running =
    true;


  CROSS_OOS_BATCH_V26.cancelled =
    false;


  CROSS_OOS_BATCH_V26.currentIndex =
    0;


  CROSS_OOS_BATCH_V26.total =
    PROVINCES.length;


  CROSS_OOS_BATCH_V26.prize =
    giaiKey;


  CROSS_OOS_BATCH_V26.results =
    [];


  CROSS_OOS_BATCH_V26.startedAt =
    new Date();


  CROSS_OOS_BATCH_V26.finishedAt =
    null;


  /*
   * Scroll tới panel.
   */

  const panel =
    getCrossOOSPanelV26();


  if (panel) {

    panel.scrollIntoView({

      behavior:
        'smooth',

      block:
        'start'

    });

  }


  try {

    for (
      let index = 0;
      index < PROVINCES.length;
      index++
    ) {

      if (
        CROSS_OOS_BATCH_V26.cancelled
      ) {

        break;

      }


      const province =
        PROVINCES[index];


      CROSS_OOS_BATCH_V26.currentIndex =
        index + 1;


      renderCrossOOSProgressV26(

        index,

        PROVINCES.length,

        province.name

      );


      /*
       * Cho browser render progress
       * trước calculation nặng.
       */

      await crossOOSWaitV26(
        120
      );


      const item =
        await runOneCrossOOSV26(
          province,
          giaiKey
        );


      CROSS_OOS_BATCH_V26.results.push(
        item
      );


      renderCrossOOSProgressV26(

        index + 1,

        PROVINCES.length,

        province.name

      );


      /*
       * Nghỉ ngắn giữa hai tỉnh.
       */

      await crossOOSWaitV26(
        120
      );

    }


    CROSS_OOS_BATCH_V26.finishedAt =
      new Date();


    if (
      CROSS_OOS_BATCH_V26.cancelled
    ) {

      renderCrossOOSCancelledV26();

      return {

        ready: false,

        cancelled: true,

        results:
          CROSS_OOS_BATCH_V26.results

      };

    }


    const summary =
      aggregateCrossProvinceOOSV26(
        CROSS_OOS_BATCH_V26.results
      );


    const classification =
      classifyCrossProvinceOOSV26(
        summary
      );


    const finalResult = {

      ready:
        Boolean(
          summary
        ),

      version:
        'V2.6',

      engine:
        'CROSS_PROVINCE_MOBILE_BATCH',

      prize:
        giaiKey,

      classification,

      summary,

      results:
        CROSS_OOS_BATCH_V26.results,

      startedAt:
        CROSS_OOS_BATCH_V26.startedAt,

      finishedAt:
        CROSS_OOS_BATCH_V26.finishedAt

    };


    renderCrossOOSFinalV26(
      finalResult
    );


    /*
     * Giữ lại kết quả để có thể
     * đọc lại bằng Console sau này.
     */

    window.LAST_CROSS_OOS_V26 =
      finalResult;


    return finalResult;


  } catch (error) {

    console.error(
      'V2.6 Cross Province Batch:',
      error
    );


    const panel =
      getCrossOOSPanelV26();


    if (panel) {

      panel.innerHTML = `

        <div
          style="
            font-size:20px;
            font-weight:900;
          "
        >
          ❌ CROSS-PROVINCE ERROR
        </div>

        <div style="margin-top:12px;">
          ${
            String(
              error.message ||
              error
            )
          }
        </div>

      `;

    }


    return null;


  } finally {

    CROSS_OOS_BATCH_V26.running =
      false;

  }

}


/* =========================================================================
   58. CANCEL BATCH
   ========================================================================= */

function cancelCrossProvinceBatchV26() {

  if (
    !CROSS_OOS_BATCH_V26.running
  ) {

    return;

  }


  CROSS_OOS_BATCH_V26.cancelled =
    true;

}


