/* =========================================================================
   21. FORMAT HELPERS
   ========================================================================= */

function provinceGateSignedV26(
  value,
  digits = 4
) {

  const n =
    Number(
      value || 0
    );


  return (
    n > 0
      ? '+'
      : ''
  ) +
  n.toFixed(
    digits
  );

}


function provinceGateColorV26(
  gate
) {

  switch (
    String(
      gate || ''
    ).toUpperCase()
  ) {

    case 'ADAPTIVE':

      return '#35d07f';


    case 'WATCH':

      return '#ffc447';


    case 'REJECT':

      return '#ff6666';


    case 'BASELINE':

      return '#b8bec8';


    default:

      return '#ffffff';

  }

}


/* =========================================================================
   22. RUN MOBILE GATE
   ========================================================================= */

function runProvinceGateMobileV26() {

  const status =
    document.getElementById(
      'provinceGateStatusV26'
    );


  const summaryBox =
    document.getElementById(
      'provinceGateSummaryV26'
    );


  const resultsBox =
    document.getElementById(
      'provinceGateResultsV26'
    );


  if (
    !status ||
    !summaryBox ||
    !resultsBox
  ) {

    return;

  }


  if (
    typeof runProvinceAdaptiveGateV26 !==
    'function'
  ) {

    status.innerHTML =
      `
        ❌ Không tìm thấy
        <b>Block 7A Engine</b>.
      `;

    return;

  }


  status.innerHTML =
    `
      ⏳ Đang phân tích
      Province Adaptive Gate...
    `;


  summaryBox.style.display =
    'none';


  resultsBox.innerHTML =
    '';


  setTimeout(
    () => {

      try {

        const result =
          runProvinceAdaptiveGateV26();


        if (
          !result ||
          !result.ready
        ) {

          const reason =
            result &&
            result.reason
              ? result.reason
              : 'UNKNOWN';


          status.innerHTML =
            `
              ⚠️ Chưa có dữ liệu
              Cross-Province OOS.

              <br><br>

              Reason:
              <b>${reason}</b>

              <br><br>

              Hãy chạy
              <b>Cross-Province OOS 21 tỉnh</b>
              trước, sau đó bấm lại
              Province Gate.
            `;


          return;

        }


        renderProvinceGateMobileV26(
          result
        );


      } catch (
        error
      ) {

        console.error(
          'V2.6 Province Gate UI:',
          error
        );


        status.innerHTML =
          `
            ❌ Province Gate Error:

            <br><br>

            <b>
              ${String(
                error.message ||
                error
              )}
            </b>
          `;

      }

    },
    50
  );

}


