/* =========================================================================
   8. PATCH DUPLICATE PROTECTION BUTTON
   ========================================================================= */

function patchSnapshotDuplicateButtonV26() {

  /*
   * Tìm button Duplicate Protection
   * từ các ID có thể đã dùng ở Block 8B.
   */

  const ids = [

    'btnSnapshotDuplicateV26',

    'btnShadowDuplicateV26',

    'btnDuplicateProtectionV26',

    'btnSnapshotDuplicateProtectionV26'

  ];


  let button =
    null;


  for (
    const id of
    ids
  ) {

    const found =
      document.getElementById(
        id
      );


    if (found) {

      button =
        found;

      break;

    }

  }


  /*
   * Nếu không biết ID,
   * tìm theo text của button.
   */

  if (!button) {

    const buttons =
      Array.from(
        document.querySelectorAll(
          'button'
        )
      );


    button =
      buttons.find(
        item => {

          const text =
            String(
              item.textContent ||
              ''
            ).toUpperCase();


          return (
            text.includes(
              'DUPLICATE'
            ) &&
            text.includes(
              'V2.6'
            )
          );

        }
      ) || null;

  }


  if (!button) {

    return false;

  }


  /*
   * Clone để loại listener cũ.
   */

  const replacement =
    button.cloneNode(
      true
    );


  replacement.onclick =
    function() {

      showSnapshotBootstrapTestV26Mobile();

    };


  button.parentNode.replaceChild(
    replacement,
    button
  );


  return true;

}


