/* =========================================================================
   XSMN V2.6 — BLOCK 8C INSPECTOR
   SNAPSHOT STORE STRUCTURE

   Mục tiêu:
   - Chỉ READ Snapshot Store hiện tại.
   - Không chạy Cross OOS.
   - Không chạy Decision Layer.
   - Không tạo snapshot.
   - Không mutate dữ liệu.
   - Research Only.
   ========================================================================= */

function inspectSnapshotStoreV26() {

  let store =
    null;

  let source =
    'NOT_FOUND';


  /*
   * -------------------------------------------------------------
   * 1. TÌM STORE ĐANG ĐƯỢC BLOCK 8B-F SỬ DỤNG
   * -------------------------------------------------------------
   */

  if (
    Array.isArray(
      window.SHADOW_SNAPSHOTS_V26
    )
  ) {

    store =
      window.SHADOW_SNAPSHOTS_V26;

    source =
      'SHADOW_SNAPSHOTS_V26';

  } else if (
    Array.isArray(
      window.SHADOW_SNAPSHOT_STORE_V26
    )
  ) {

    store =
      window.SHADOW_SNAPSHOT_STORE_V26;

    source =
      'SHADOW_SNAPSHOT_STORE_V26';

  } else if (
    Array.isArray(
      window.LAST_SHADOW_SNAPSHOTS_V26
    )
  ) {

    store =
      window.LAST_SHADOW_SNAPSHOTS_V26;

    source =
      'LAST_SHADOW_SNAPSHOTS_V26';

  }


  /*
   * -------------------------------------------------------------
   * 2. STORE KHÔNG TỒN TẠI
   * -------------------------------------------------------------
   */

  if (
    !Array.isArray(
      store
    )
  ) {

    return {

      ready: false,

      reason:
        'SNAPSHOT_STORE_NOT_FOUND',

      source

    };

  }


  /*
   * -------------------------------------------------------------
   * 3. STORE RỖNG
   * -------------------------------------------------------------
   */

  if (
    !store.length
  ) {

    return {

      ready: false,

      reason:
        'SNAPSHOT_STORE_EMPTY',

      source,

      total:
        0

    };

  }


  /*
   * -------------------------------------------------------------
   * 4. CHỈ ĐỌC SNAPSHOT ĐẦU TIÊN
   * -------------------------------------------------------------
   */

  const sample =
    store[0];


  return {

    ready: true,

    source,

    total:
      store.length,

    pending:
      store.filter(
        item =>
          String(
            item.status || ''
          ).toUpperCase() ===
          'PENDING'
      ).length,

    verified:
      store.filter(
        item =>
          String(
            item.status || ''
          ).toUpperCase() ===
          'VERIFIED'
      ).length,

    sampleKeys:
      sample &&
      typeof sample ===
        'object'
        ? Object.keys(
            sample
          )
        : [],

    sample

  };

}


