/* =========================================================================
   XSMN V2.6 — FINAL PERSISTENCE SCHEMA FIX

   Mục tiêu:
   1. Một schema duy nhất:
      {
        version,
        updatedAt,
        snapshots: []
      }

   2. readShadowSnapshotsV26()
      đọc được:
      - Wrapper schema mới
      - Legacy Array schema cũ

   3. writeShadowSnapshotsV26()
      luôn ghi Wrapper schema.

   4. persistCurrentShadowSnapshotsV26()
      KHÔNG cho RAM [] ghi đè persistent đang có dữ liệu.

   5. Không thay Production Prediction Engine.
   Research Only.
   ========================================================================= */


/* =========================================================================
   1. COMPATIBLE READ
   ========================================================================= */

readShadowSnapshotsV26 =
function () {

  try {

    const read =
      readShadowPersistentWrapperV26();


    if (
      !read ||
      !read.ready ||
      !read.store ||
      !Array.isArray(
        read.store.snapshots
      )
    ) {

      return [];

    }


    return read
      .store
      .snapshots
      .slice();

  } catch (error) {

    console.error(
      'V2.6 Final Snapshot Read Error:',
      error
    );


    return [];

  }

};


/* =========================================================================
   2. UNIFIED WRAPPER WRITE
   ========================================================================= */

writeShadowSnapshotsV26 =
function (
  snapshots
) {

  if (
    !Array.isArray(
      snapshots
    )
  ) {

    return false;

  }


  try {

    /*
     * Giữ giới hạn cũ nếu config tồn tại.
     */

    const maxSnapshots =
      (
        typeof
          SHADOW_TRACKING_V26_CONFIG !==
        'undefined' &&
        SHADOW_TRACKING_V26_CONFIG &&
        Number.isFinite(
          Number(
            SHADOW_TRACKING_V26_CONFIG
              .maxSnapshots
          )
        )
      )
        ? Number(
            SHADOW_TRACKING_V26_CONFIG
              .maxSnapshots
          )
        : 500;


    const limited =
      snapshots.slice(
        -maxSnapshots
      );


    const result =
      writeShadowPersistentWrapperV26(
        limited
      );


    return Boolean(
      result &&
      result.ready
    );

  } catch (error) {

    console.error(
      'V2.6 Final Snapshot Write Error:',
      error
    );


    return false;

  }

};


/* =========================================================================
   3. SAFE RAM -> PERSISTENT

   Quy tắc:
   - RAM có dữ liệu -> được ghi.
   - RAM [] + persistent [] -> được giữ rỗng.
   - RAM [] + persistent có dữ liệu
     -> KHÔNG được overwrite.
   ========================================================================= */

persistCurrentShadowSnapshotsV26 =
function () {

  const ram =
    window
      .SHADOW_SNAPSHOTS_V26;


  if (
    !Array.isArray(
      ram
    )
  ) {

    return {

      ready: false,

      reason:
        'RAM_STORE_NOT_ARRAY'

    };

  }


  /*
   * -------------------------------------------------------------
   * RAM có snapshot:
   * ghi bình thường.
   * -------------------------------------------------------------
   */

  if (
    ram.length > 0
  ) {

    return (
      writeShadowPersistentWrapperV26(
        ram
      )
    );

  }


  /*
   * -------------------------------------------------------------
   * RAM đang rỗng.
   * Đọc persistent trước khi quyết định.
   * -------------------------------------------------------------
   */

  const existing =
    readShadowPersistentWrapperV26();


  if (
    !existing ||
    !existing.ready
  ) {

    return {

      ready: false,

      reason:
        existing &&
        existing.reason
          ? existing.reason
          : 'PERSISTENT_READ_NOT_READY',

      protected:
        true

    };

  }


  const persistentSnapshots =
    (
      existing.store &&
      Array.isArray(
        existing.store.snapshots
      )
    )
      ? existing
          .store
          .snapshots
      : [];


  /*
   * Persistent đang có dữ liệu:
   * tuyệt đối không cho RAM [] ghi đè.
   */

  if (
    persistentSnapshots.length > 0
  ) {

    /*
     * Đồng bộ RAM trở lại từ persistent.
     */

    window.SHADOW_SNAPSHOTS_V26 =
      persistentSnapshots.slice();


    return {

      ready: true,

      source:
        'EMPTY_RAM_WRITE_BLOCKED',

      protected:
        true,

      restored:
        true,

      count:
        persistentSnapshots.length,

      store:
        existing.store

    };

  }


  /*
   * Cả RAM và persistent đều rỗng.
   * Không cần write thêm một wrapper rỗng.
   */

  return {

    ready: true,

    source:
      'EMPTY_STORE_NO_WRITE',

    protected:
      true,

    restored:
      false,

    count:
      0,

    store:
      existing.store

  };

};


/* =========================================================================
   4. FINAL FIX MARKER
   ========================================================================= */

window
  .V26_FINAL_PERSISTENCE_SCHEMA_FIX =
  true;


console.log(
  'XSMN V2.6 Final Persistence Schema Fix: ACTIVE'
);

/* =========================================================================
   XSMN V2.6 — 8C-A6
   SHADOW BRIDGE -> WRAPPER PERSISTENCE FIX

   Mục tiêu:
   - Bridge Store dùng chung Wrapper Schema.
   - Không còn writer array riêng.
   - RAM và localStorage đồng bộ cùng dữ liệu.
   - Không thay Production Prediction Engine.
   ========================================================================= */

writeShadowSnapshotStoreBridgeV26 =
function (
  rows
) {

  if (
    !Array.isArray(
      rows
    )
  ) {

    return {

      ready: false,

      reason:
        'INVALID_SNAPSHOT_STORE'

    };

  }


  try {

    /*
     * Writer chuẩn duy nhất:
     *
     * {
     *   version: 'V2.6',
     *   updatedAt: ...,
     *   snapshots: [...]
     * }
     */

    const write =
      writeShadowPersistentWrapperV26(
        rows
      );


    if (
      !write ||
      !write.ready
    ) {

      return {

        ready: false,

        reason:
          write &&
          write.reason
            ? write.reason
            : 'WRAPPER_WRITE_FAILED',

        write

      };

    }


    /*
     * Clone RAM để tránh cùng reference
     * với array đang được Bridge xử lý.
     */

    window.SHADOW_SNAPSHOTS_V26 =
      rows.slice();


    window.LAST_SHADOW_SNAPSHOTS_V26 =
      rows.slice();


    return {

      ready: true,

      schema:
        'WRAPPER',

      count:
        rows.length,

      persistentCount:
        write.count != null
          ? write.count
          : rows.length,

      protected:
        true

    };


  } catch (error) {

    return {

      ready: false,

      reason:
        'SNAPSHOT_WRAPPER_WRITE_ERROR',

      error:
        String(
          error.message ||
          error
        )

    };

  }

};


window.V26_SHADOW_BRIDGE_WRAPPER_FIX =
  true;


console.log(
  'XSMN V2.6 Shadow Bridge Wrapper Fix: ACTIVE'
);

/* =========================================================================
   XSMN V2.6 — BLOCK 8C-B1
   PENDING SNAPSHOT DIAGNOSTIC

   Mục tiêu:
   - Đọc snapshot từ persistent wrapper đã PASS ở 8C-A.
   - Xác định snapshot nào đang PENDING.
   - Kiểm tra draw identity tại thời điểm prediction.
   - Chưa verify.
   - Chưa update snapshot.
   - Không ghi localStorage.
   - Không thay Production Prediction Engine.

   RESEARCH ONLY.
   ========================================================================= */


/* =========================================================================
   1. NORMALIZE SNAPSHOT VERIFICATION STATUS
   ========================================================================= */

function getShadowSnapshotVerificationStatusV26(
  snapshot
) {

  if (
    !snapshot ||
    typeof snapshot !==
      'object'
  ) {

    return 'INVALID';

  }


  /*
   * Schema mới:
   * verification.status
   */

  if (
    snapshot.verification &&
    snapshot.verification.status
  ) {

    return String(
      snapshot
        .verification
        .status
    ).toUpperCase();

  }


  /*
   * Một số snapshot bridge cũ
   * có thể dùng status trực tiếp.
   */

  if (
    snapshot.status
  ) {

    return String(
      snapshot.status
    ).toUpperCase();

  }


  /*
   * Schema cũ hơn có evaluated.
   */

  if (
    snapshot.evaluated === true
  ) {

    return 'VERIFIED';

  }


  return 'PENDING';

}


/* =========================================================================
   2. READ SNAPSHOTS FOR 8C-B

   Chỉ READ.
   Ưu tiên wrapper chuẩn 8C-A.
   ========================================================================= */

function readPendingDiagnosticSnapshotsV26() {

  try {

    /*
     * Reader wrapper chuẩn.
     */

    if (
      typeof
        readShadowPersistentWrapperV26 ===
      'function'
    ) {

      const read =
        readShadowPersistentWrapperV26();


      if (
        read &&
        read.ready &&
        read.store &&
        Array.isArray(
          read.store.snapshots
        )
      ) {

        return {

          ready: true,

          source:
            'PERSISTENT_WRAPPER',

          snapshots:
            read.store
              .snapshots
              .slice()

        };

      }

    }


    /*
     * Fallback reader đã được
     * Final Persistence Fix override.
     */

    if (
      typeof
        readShadowSnapshotsV26 ===
      'function'
    ) {

      const snapshots =
        readShadowSnapshotsV26();


      if (
        Array.isArray(
          snapshots
        )
      ) {

        return {

          ready: true,

          source:
            'SNAPSHOT_READER',

          snapshots:
            snapshots.slice()

        };

      }

    }


    /*
     * Cuối cùng mới fallback RAM.
     */

    if (
      Array.isArray(
        window.SHADOW_SNAPSHOTS_V26
      )
    ) {

      return {

        ready: true,

        source:
          'RAM_FALLBACK',

        snapshots:
          window
            .SHADOW_SNAPSHOTS_V26
            .slice()

      };

    }


    return {

      ready: false,

      reason:
        'SNAPSHOT_STORE_NOT_FOUND',

      snapshots: []

    };


  } catch (error) {

    return {

      ready: false,

      reason:
        'SNAPSHOT_DIAGNOSTIC_READ_ERROR',

      error:
        String(
          error.message ||
          error
        ),

      snapshots: []

    };

  }

}


/* =========================================================================
   3. INSPECT ONE PENDING SNAPSHOT

   Chưa resolve actual result ở B1.
   B1 chỉ xác định đầy đủ identity
   trước khi B2 nối historical resolver.
   ========================================================================= */

function inspectPendingShadowSnapshotV26(
  snapshot,
  index
) {

  const status =
    getShadowSnapshotVerificationStatusV26(
      snapshot
    );


  const province =
    snapshot &&
    snapshot.province
      ? snapshot.province
      : null;


  const prize =
    snapshot &&
    snapshot.prize
      ? snapshot.prize
      : 'db';


  const latestDrawDate =
    snapshot &&
    snapshot.latestDrawDate
      ? snapshot.latestDrawDate
      : null;


  const latestDrawKey =
    snapshot &&
    snapshot.latestDrawKey
      ? snapshot.latestDrawKey
      : null;


  const generatedAt =
    snapshot &&
    (
      snapshot.generatedAt ||
      snapshot.savedAt ||
      snapshot.createdAt
    )
      ? (
          snapshot.generatedAt ||
          snapshot.savedAt ||
          snapshot.createdAt
        )
      : null;


  const snapshotKey =
    snapshot &&
    snapshot.snapshotKey
      ? snapshot.snapshotKey
      : null;


  return {

    index,

    ready:
      Boolean(
        snapshot &&
        typeof snapshot ===
          'object' &&
        province
      ),

    status,

    pending:
      status ===
      'PENDING',

    province,

    prize,

    model:
      snapshot &&
      snapshot.model
        ? snapshot.model
        : null,

    window:
      snapshot &&
      snapshot.window != null
        ? snapshot.window
        : null,

    latestDrawDate,

    latestDrawKey,

    generatedAt,

    snapshotKey,

    hasTop1:
      Boolean(
        snapshot &&
        Array.isArray(
          snapshot.top1
        ) &&
        snapshot.top1.length
      ),

    hasTop3:
      Boolean(
        snapshot &&
        Array.isArray(
          snapshot.top3
        ) &&
        snapshot.top3.length
      ),

    hasTop5:
      Boolean(
        snapshot &&
        Array.isArray(
          snapshot.top5
        ) &&
        snapshot.top5.length
      ),

    hasTop10:
      Boolean(
        snapshot &&
        Array.isArray(
          snapshot.top10
        ) &&
        snapshot.top10.length
      )

  };

}


/* =========================================================================
   4. RUN 8C-B1 DIAGNOSTIC
   ========================================================================= */

function debugPendingShadowSnapshotsV26() {

  const read =
    readPendingDiagnosticSnapshotsV26();


  if (
    !read.ready
  ) {

    return {

      ready: false,

      version:
        'V2.6',

      block:
        '8C-B1',

      reason:
        read.reason,

      error:
        read.error ||
        null

    };

  }


  const rows =
    read.snapshots.map(
      (
        snapshot,
        index
      ) =>
        inspectPendingShadowSnapshotV26(
          snapshot,
          index
        )
    );


  const valid =
    rows.filter(
      row =>
        row.ready
    );


  const pending =
    valid.filter(
      row =>
        row.pending
    );


  const verified =
    valid.filter(
      row =>
        row.status ===
        'VERIFIED'
    );


  const missingDrawIdentity =
    pending.filter(
      row =>
        !row.latestDrawDate ||
        !row.latestDrawKey
    );


  const missingRanking =
    pending.filter(
      row =>
        !row.hasTop1 ||
        !row.hasTop3
    );


  return {

    ready: true,

    version:
      'V2.6',

    block:
      '8C-B1',

    engine:
      'PENDING_SNAPSHOT_DIAGNOSTIC',

    researchOnly:
      true,

    readOnly:
      true,

    source:
      read.source,

    totalSnapshots:
      rows.length,

    validSnapshots:
      valid.length,

    pendingCount:
      pending.length,

    verifiedCount:
      verified.length,

    missingDrawIdentity:
      missingDrawIdentity.length,

    missingRanking:
      missingRanking.length,

    pending,

    rows

  };

}


