/* =========================================================================
   V2.6 — 8C-B8
   STARTUP AUTO VERIFICATION

   Mục tiêu:
   - Chạy sau B7 Startup Recovery.
   - Kiểm tra snapshot PENDING.
   - Nếu đã có target draw -> B3 verify.
   - B3 chịu trách nhiệm persist VERIFIED.
   - Không tạo snapshot mới.
   ========================================================================= */

function runStartupAutoVerificationV26() {

  /*
   * Guard B7.
   *
   * Không chạy startup verification nếu
   * lifecycle chưa được recovery.
   */

  const recovery =
    window.LAST_V26_B7_RECOVERY;


  if (
    !recovery ||
    !recovery.ready ||
    !recovery.recovered
  ) {

    const result = {

      ready: false,

      ran: false,

      reason:
        'B7_STARTUP_RECOVERY_NOT_READY'

    };


    window.LAST_V26_B8_STARTUP_VERIFY =
      result;


    return result;

  }


  /*
   * Guard B9 Safe Verification Gate.
   *
   * Startup không được gọi trực tiếp B3.
   * Mọi verification phải đi qua Safe Gate.
   */

  if (
    typeof runSafeShadowVerificationV26 !==
      'function'
  ) {

    const result = {

      ready: false,

      ran: false,

      reason:
        'B9_SAFE_VERIFICATION_GATE_NOT_AVAILABLE'

    };


    window.LAST_V26_B8_STARTUP_VERIFY =
      result;


    return result;

  }


  /*
   * Chạy Safe Verification Gate.
   *
   * WAITING:
   * Gate chạy nhưng B3 không được execute.
   *
   * AVAILABLE:
   * Gate cho phép B3 verify.
   */

  let verification;


  try {

    verification =
      runSafeShadowVerificationV26();

  } catch (
    error
  ) {

    const result = {

      ready: false,

      ran: true,

      reason:
        'STARTUP_VERIFICATION_EXCEPTION',

      error:
        String(
          error &&
          error.message
            ? error.message
            : error
        )

    };


    window.LAST_V26_B8_STARTUP_VERIFY =
      result;


    console.error(
      'V2.6 B9 C3 Startup Safe Verification:',
      result
    );


    return result;

  }


  /*
   * Normalize Safe Gate result.
   */

  const result = {

    ready:
      Boolean(
        verification &&
        verification.ready
      ),

    ran: true,

    version:
      'V2.6',

    engine:
      'B9_C3_STARTUP_SAFE_AUTO_VERIFICATION',

    researchOnly:
      true,

    /*
     * Safe Gate state.
     */

    gateReady:
      Boolean(
        verification &&
        verification.ready
      ),

    allowed:
      Boolean(
        verification &&
        verification.allowed
      ),

    executed:
      Boolean(
        verification &&
        verification.executed
      ),

    waiting:
      Boolean(
        verification &&
        verification.waiting
      ),

    blocked:
      Boolean(
        verification &&
        verification.blocked
      ),

    reason:
      verification &&
      verification.reason
        ? verification.reason
        : null,

    /*
     * Snapshot lifecycle.
     */

    pending:
      verification &&
      verification.pending != null
        ? verification.pending
        : null,

    readyToVerify:
      verification &&
      verification.readyToVerify != null
        ? verification.readyToVerify
        : null,

    waitingCount:
      verification &&
      verification.waitingCount != null
        ? verification.waitingCount
        : null,

    /*
     * B3 result.
     *
     * Các field này chỉ được populated
     * khi Safe Gate thực sự execute B3.
     */

    requested:
      verification &&
      verification.requested != null
        ? verification.requested
        : 0,

    verifiedNew:
      verification &&
      verification.verified != null
        ? verification.verified
        : 0,

    stillPending:
      verification &&
      verification.stillPending != null
        ? verification.stillPending
        : (
            verification &&
            verification.pending != null
              ? verification.pending
              : 0
          ),

    alreadyVerified:
      verification &&
      verification.alreadyVerified != null
        ? verification.alreadyVerified
        : 0,

    failed:
      verification &&
      verification.failed != null
        ? verification.failed
        : 0,

    saved:
      Boolean(
        verification &&
        verification.saved
      ),

    /*
     * Giữ nguyên toàn bộ Safe Gate
     * diagnostic để audit.
     */

    verification

  };


  window.LAST_V26_B8_STARTUP_VERIFY =
    result;


  console.log(
    'V2.6 B9 C3 Startup Safe Verification:',
    result
  );


  return result;

}

/* =========================================================================
   V2.6 — 8C-B8
   STARTUP AUTO VERIFICATION DIAGNOSTIC

   READ ONLY:
   - Không gọi verifier lần nữa.
   - Không ghi localStorage.
   - Chỉ đọc LAST_V26_B8_STARTUP_VERIFY.
   ========================================================================= */

function testStartupAutoVerificationV26() {

  const startup =
    window.LAST_V26_B8_STARTUP_VERIFY;


  if (!startup) {

    return {

      ready: false,

      passed: false,

      reason:
        'B8_STARTUP_RESULT_NOT_FOUND'

    };

  }


  if (!startup.ran) {

    return {

      ready: false,

      passed: false,

      reason:
        startup.reason ||
        'B8_STARTUP_NOT_RUN',

      startup

    };

  }


  const gate =
    startup.verification;


  if (
    !gate ||
    typeof gate !==
      'object'
  ) {

    return {

      ready: false,

      passed: false,

      reason:
        'B9_SAFE_GATE_RESULT_NOT_FOUND',

      startup

    };

  }


  /*
   * -------------------------------------------------------------
   * B9 C5 STARTUP SAFE-GATE DIAGNOSTIC
   *
   * Startup không còn yêu cầu B3 phải
   * luôn được execute.
   *
   * Có 2 đường PASS hợp lệ:
   *
   * 1. WAITING / BLOCKED
   *    Gate ready
   *    allowed = false
   *    executed = false
   *
   * 2. ALLOWED
   *    Gate ready
   *    allowed = true
   *    executed = true
   *    failed = 0
   * -------------------------------------------------------------
   */

  const waitingPath =
    (
      gate.ready === true &&
      gate.allowed === false &&
      gate.executed === false
    );


  const allowedPath =
    (
      gate.ready === true &&
      gate.allowed === true &&
      gate.executed === true &&
      Number(
        gate.failed || 0
      ) === 0
    );


  const passed =
    (
      startup.ran === true &&
      startup.ready === true &&
      (
        waitingPath ||
        allowedPath
      )
    );


  /*
   * verifiedExisting:
   *
   * Khi Gate không execute B3,
   * gate.verified là số VERIFIED
   * đang tồn tại trong lifecycle.
   *
   * verifiedNew chỉ được phép lấy
   * khi B3 thực sự executed.
   */

  const verifiedExisting =
    gate.verified != null
      ? Number(
          gate.verified
        )
      : 0;


  const verifiedNew =
    gate.executed === true &&
    gate.verified != null
      ? Number(
          gate.verified
        )
      : 0;


  const result = {

    ready: true,

    passed,

    version:
      'V2.6',

    engine:
      'B9_C5_STARTUP_SAFE_GATE_DIAGNOSTIC',

    researchOnly:
      true,

    autoTriggered:
      startup.ran === true,

    gateReady:
      Boolean(
        gate.ready
      ),

    allowed:
      Boolean(
        gate.allowed
      ),

    executed:
      Boolean(
        gate.executed
      ),

    waiting:
      Boolean(
        gate.waiting
      ),

    blocked:
      Boolean(
        gate.blocked
      ),

    reason:
      gate.reason ||
      null,

    pending:
      gate.pending != null
        ? gate.pending
        : null,

    readyToVerify:
      gate.readyToVerify != null
        ? gate.readyToVerify
        : null,

    waitingCount:
      gate.waitingCount != null
        ? gate.waitingCount
        : null,

    verifiedExisting,

    verifiedNew,

    requested:
      gate.executed === true &&
      gate.requested != null
        ? gate.requested
        : 0,

    stillPending:
      gate.stillPending != null
        ? gate.stillPending
        : (
            gate.pending != null
              ? gate.pending
              : 0
          ),

    alreadyVerified:
      gate.executed === true &&
      gate.alreadyVerified != null
        ? gate.alreadyVerified
        : 0,

    failed:
      gate.executed === true &&
      gate.failed != null
        ? gate.failed
        : 0,

    saved:
      gate.executed === true
        ? Boolean(
            gate.saved
          )
        : false

  };


  window.LAST_V26_B8_TEST =
    result;


  return result;

}


