/* =========================================================================
   XSMN V2.6 — B8 VERIFICATION PREFLIGHT
   READ ONLY

   Mục tiêu:
   - Kiểm tra snapshot PENDING nào đã có target draw.
   - Không gọi verifier.
   - Không gọi writer.
   - Không thay RAM.
   - Không thay persistent store.
   ========================================================================= */

function preflightPendingShadowVerificationV26() {

  const persistent =
    readShadowPersistentWrapperV26();


  if (
    !persistent ||
    !persistent.ready ||
    !persistent.store ||
    !Array.isArray(
      persistent.store.snapshots
    )
  ) {

    return {

      ready: false,

      reason:
        'PERSISTENT_STORE_NOT_READY'

    };

  }


  const snapshots =
    persistent.store.snapshots;


  let pending =
    0;

  let readyToVerify =
    0;

  let waiting =
    0;

  let errors =
    0;


  const details =
    [];


  snapshots.forEach(
    snapshot => {

      const status =
        String(
          snapshot.status ||
          (
            snapshot.verification &&
            snapshot.verification.status
          ) ||
          'PENDING'
        )
          .toUpperCase();


      if (
        status !==
        'PENDING'
      ) {

        return;

      }


      pending++;


      /*
       * Chỉ kiểm tra identity.
       */

      if (
        !snapshot.targetDrawDate ||
        !snapshot.targetDrawKey
      ) {

        errors++;


        details.push({

          province:
            snapshot.province ||
            snapshot.provinceSlug ||
            '-',

          targetDrawDate:
            snapshot.targetDrawDate ||
            '-',

          state:
            'ERROR',

          reason:
            'TARGET_DRAW_IDENTITY_NOT_READY'

        });


        return;

      }


      /*
       * READ ONLY lookup.
       *
       * findShadowTargetDrawV26()
       * chỉ tìm draw, không verify
       * và không persist.
       */

      const target =
        findShadowTargetDrawV26(
          snapshot
        );


      if (
        target.ready
      ) {

        readyToVerify++;


        details.push({

          province:
            target.province,

          targetDrawDate:
            target.targetDrawDate,

          state:
            'READY_TO_VERIFY',

          reason:
            'TARGET_DRAW_AVAILABLE'

        });


        return;

      }


      if (
        target.pending
      ) {

        waiting++;


        details.push({

          province:
            snapshot.province ||
            snapshot.provinceSlug ||
            '-',

          targetDrawDate:
            snapshot.targetDrawDate ||
            '-',

          state:
            'WAITING',

          reason:
            target.reason,

          availableLatestDate:
            target.availableLatestDate ||
            null

        });


        return;

      }


      errors++;


      details.push({

        province:
          snapshot.province ||
          snapshot.provinceSlug ||
          '-',

        targetDrawDate:
          snapshot.targetDrawDate ||
          '-',

        state:
          'ERROR',

        reason:
          target.reason ||
          'UNKNOWN_PREFLIGHT_ERROR'

      });

    }
  );


  return {

    ready:
      errors === 0,

    version:
      'V2.6',

    engine:
      'B8_VERIFICATION_PREFLIGHT',

    researchOnly:
      true,

    readOnly:
      true,

    total:
      snapshots.length,

    pending,

    readyToVerify,

    waiting,

    errors,

    details

  };

}


