/* =========================================================================
   XSMN V2.6 — B9
   REAL DRAW LIFECYCLE OBSERVER

   READ ONLY

   Mục tiêu:
   - Quan sát lifecycle snapshot thật.
   - Tái sử dụng B8 Verification Preflight.
   - Không gọi verifier.
   - Không gọi writer.
   - Không thay RAM.
   - Không thay persistent store.
   ========================================================================= */

function observeRealDrawLifecycleV26() {

  /*
   * -------------------------------------------------------------
   * PREFLIGHT
   * -------------------------------------------------------------
   */

  if (
    typeof
      preflightPendingShadowVerificationV26 !==
    'function'
  ) {

    return {

      ready: false,

      reason:
        'B8_PREFLIGHT_NOT_AVAILABLE'

    };

  }


  const preflight =
    preflightPendingShadowVerificationV26();


  if (
    !preflight ||
    (
      !preflight.ready &&
      preflight.total == null
    )
  ) {

    return {

      ready: false,

      reason:
        preflight &&
        preflight.reason
          ? preflight.reason
          : 'B9_PREFLIGHT_FAILED',

      preflight

    };

  }


  /*
   * -------------------------------------------------------------
   * PERSISTENT SNAPSHOTS
   * -------------------------------------------------------------
   */

  const persistent =
    readShadowPersistentWrapperV26();


  if (
    !persistent ||
    !persistent.ready ||
    !persistent.store ||
    !Array.isArray(
      persistent.store.snapshots
    )
  ) {

    return {

      ready: false,

      reason:
        'B9_PERSISTENT_STORE_NOT_READY',

      preflight

    };

  }


  const snapshots =
    persistent.store.snapshots;


  let pending =
    0;

  let verified =
    0;

  let other =
    0;


  const verifiedDetails =
    [];


  snapshots.forEach(
    snapshot => {

      const status =
        String(
          snapshot.status ||
          (
            snapshot.verification &&
            snapshot.verification.status
          ) ||
          'PENDING'
        )
          .toUpperCase();


      if (
        status ===
        'PENDING'
      ) {

        pending++;

        return;

      }


      if (
        status ===
        'VERIFIED'
      ) {

        verified++;


        const verification =
          snapshot.verification ||
          {};


        verifiedDetails.push({

          id:
            snapshot.id ||
            null,

          province:
            snapshot.provinceSlug ||
            snapshot.province ||
            snapshot.slug ||
            '-',

          targetDrawDate:
            snapshot.targetDrawDate ||
            '-',

          actualDb:
            snapshot.actual != null
              ? String(
                  snapshot.actual
                )
              : null,

          actualTarget:
            snapshot.actualTarget != null
              ? String(
                  snapshot.actualTarget
                )
              : null,

          rank:
            verification.rank != null
              ? verification.rank
              : null,

          top1Hit:
            verification.top1Hit === true,

          top3Hit:
            verification.top3Hit === true,

          top5Hit:
            verification.top5Hit === true,

          top10Hit:
            verification.top10Hit === true,

          verifiedAt:
            verification.verifiedAt ||
            null

        });


        return;

      }


      other++;

    }
  );


  /*
   * -------------------------------------------------------------
   * RAM CONSISTENCY
   * -------------------------------------------------------------
   */

  const ram =
    Array.isArray(
      window.SHADOW_SNAPSHOTS_V26
    )
      ? window.SHADOW_SNAPSHOTS_V26
      : [];


  const lastRam =
    Array.isArray(
      window.LAST_SHADOW_SNAPSHOTS_V26
    )
      ? window.LAST_SHADOW_SNAPSHOTS_V26
      : [];


  const identityOf =
    snapshot =>
      String(
        snapshot &&
        (
          snapshot.id ||
          snapshot.snapshotKey ||
          ''
        )
      );


  const persistentIds =
    snapshots.map(
      identityOf
    );


  const ramIds =
    ram.map(
      identityOf
    );


  const lastRamIds =
    lastRam.map(
      identityOf
    );


  const ramMatch =
    JSON.stringify(
      persistentIds
    ) ===
    JSON.stringify(
      ramIds
    );


  const lastRamMatch =
    JSON.stringify(
      persistentIds
    ) ===
    JSON.stringify(
      lastRamIds
    );


  /*
   * -------------------------------------------------------------
   * LIFECYCLE STATE
   * -------------------------------------------------------------
   */

  let lifecycleState =
    'WAITING';


  if (
    verified > 0
  ) {

    lifecycleState =
      'VERIFIED_EXISTS';

  } else if (
    preflight.readyToVerify > 0
  ) {

    lifecycleState =
      'READY_TO_VERIFY';

  } else if (
    preflight.errors > 0
  ) {

    lifecycleState =
      'ERROR';

  }


  const result = {

    ready:
      preflight.errors === 0,

    version:
      'V2.6',

    engine:
      'B9_REAL_DRAW_LIFECYCLE_OBSERVER',

    researchOnly:
      true,

    readOnly:
      true,

    lifecycleState,

    total:
      snapshots.length,

    pending,

    verified,

    other,

    readyToVerify:
      preflight.readyToVerify,

    waiting:
      preflight.waiting,

    errors:
      preflight.errors,

    persistentCount:
      snapshots.length,

    ramCount:
      ram.length,

    lastRamCount:
      lastRam.length,

    ramMatch,

    lastRamMatch,

    preflightDetails:
      Array.isArray(
        preflight.details
      )
        ? preflight.details
        : [],

    verifiedDetails

  };


  window.LAST_V26_B9_OBSERVER =
    result;


  return result;

}


