/* =========================================================================
   XSMN V2.6 — FIX-01B
   CANONICAL SHADOW PERSISTENCE READER

   Mục tiêu:
   - ONE canonical persistent key.
   - ONE canonical reader contract.
   - Legacy readers chỉ là compatibility adapter.
   - Không biến persistent corruption thành empty store.
   - Không thay Production Prediction Engine.
   ========================================================================= */

const SHADOW_CANONICAL_STORE_KEY_V26 =
  'XSMN_V26_SHADOW_SNAPSHOTS';


function readCanonicalShadowStoreV26() {

  /*
   * Canonical reader hiện tại.
   */

  const result =
    readShadowPersistentWrapperV26();


  if (
    !result ||
    result.ready !== true ||
    !result.store ||
    !Array.isArray(
      result.store.snapshots
    )
  ) {

    return {

      ready: false,

      reason:
        result &&
        result.reason
          ? result.reason
          : 'CANONICAL_STORE_NOT_READY',

      corrupted:
        Boolean(
          result &&
          (
            result.reason ===
              'PERSISTENT_JSON_INVALID' ||
            result.reason ===
              'UNKNOWN_PERSISTENT_SCHEMA'
          )
        ),

      store:
        null,

      snapshots:
        null

    };

  }


  const snapshots =
    result.store.snapshots
      .slice();


  return {

    ready: true,

    source:
      result.source ||
      'CANONICAL_WRAPPER',

    key:
      SHADOW_CANONICAL_STORE_KEY_V26,

    store:
      result.store,

    snapshots,

    total:
      snapshots.length

  };

}


/*
 * -------------------------------------------------------------
 * LEGACY READ ADAPTER
 *
 * Các caller cũ vẫn nhận Array.
 *
 * Nhưng khi canonical store lỗi:
 * KHÔNG giả vờ rằng store rỗng.
 * -------------------------------------------------------------
 */

readShadowSnapshotsV26 =
function () {

  const result =
    readCanonicalShadowStoreV26();


  if (
    !result.ready
  ) {

    console.error(
      'V2.6 FIX-01B Canonical Read Blocked:',
      result
    );


    window.LAST_V26_CANONICAL_READ_ERROR =
      result;


    /*
     * Legacy API bắt buộc phải trả Array
     * để không phá caller cũ.
     *
     * Nhưng đánh dấu lỗi rõ ràng để writer /
     * lifecycle guard không được coi đây là
     * authoritative empty state.
     */

    return [];

  }


  window.LAST_V26_CANONICAL_READ_ERROR =
    null;


  return result.snapshots.slice();

};


/*
 * -------------------------------------------------------------
 * BRIDGE READ ADAPTER
 *
 * Retire key:
 * XSMN_SHADOW_SNAPSHOTS_V26
 *
 * Bridge từ đây đọc canonical store.
 * -------------------------------------------------------------
 */

readShadowSnapshotStoreBridgeV26 =
function () {

  const result =
    readCanonicalShadowStoreV26();


  if (
    !result.ready
  ) {

    console.error(
      'V2.6 FIX-01B Bridge Read Blocked:',
      result
    );


    return [];

  }


  return result.snapshots.slice();

};


console.log(
  'XSMN V2.6 FIX-01B — Canonical Persistence Reader ACTIVE'
);

/* =========================================================================
   XSMN V2.6 — FIX-01C
   CANONICAL SHADOW PERSISTENCE WRITER

   Mục tiêu:
   - ONE canonical writer.
   - Tất cả legacy writer đi qua canonical writer.
   - Chỉ dùng canonical storage key.
   - Giữ Empty Write Guard hiện có.
   - RAM chỉ sync sau persistent write thành công.
   - Không thay Production Prediction Engine.
   ========================================================================= */


/* =========================================================================
   1. CANONICAL WRITER
   ========================================================================= */

function writeCanonicalShadowStoreV26(
  snapshots
) {

  if (
    !Array.isArray(
      snapshots
    )
  ) {

    return {

      ready: false,

      written: false,

      reason:
        'CANONICAL_SNAPSHOTS_NOT_ARRAY'

    };

  }


  /*
   * Writer thấp nhất hiện tại đã có:
   * - Wrapper schema
   * - Empty-write protection
   * - RAM synchronization
   */

  const result =
    writeShadowPersistentWrapperV26(
      snapshots.slice()
    );


  if (
    !result ||
    result.ready !== true
  ) {

    const failure = {

      ready: false,

      written: false,

      reason:
        result &&
        result.reason
          ? result.reason
          : 'CANONICAL_WRITE_FAILED',

      write:
        result ||
        null

    };


    window.LAST_V26_CANONICAL_WRITE =
      failure;


    return failure;

  }


  const success = {

    ready: true,

    written:
      result.blocked !== true,

    blocked:
      result.blocked === true,

    protected:
      result.protected === true,

    source:
      result.source ||
      'CANONICAL_WRAPPER_WRITER',

    key:
      SHADOW_CANONICAL_STORE_KEY_V26,

    count:
      result.count != null
        ? result.count
        : snapshots.length,

    write:
      result

  };


  window.LAST_V26_CANONICAL_WRITE =
    success;


  return success;

}


/* =========================================================================
   2. LEGACY BOOLEAN WRITER ADAPTER
   ========================================================================= */

writeShadowSnapshotsV26 =
function (
  snapshots
) {

  const result =
    writeCanonicalShadowStoreV26(
      snapshots
    );


  /*
   * Legacy callers của function này
   * đang mong boolean.
   */

  return Boolean(
    result &&
    result.ready
  );

};


/* =========================================================================
   3. BRIDGE WRITER ADAPTER
   ========================================================================= */

writeShadowSnapshotStoreBridgeV26 =
function (
  rows
) {

  const result =
    writeCanonicalShadowStoreV26(
      rows
    );


  /*
   * Bridge callers đang mong object
   * có property ready.
   */

  if (
    !result ||
    !result.ready
  ) {

    return {

      ready: false,

      reason:
        result &&
        result.reason
          ? result.reason
          : 'CANONICAL_BRIDGE_WRITE_FAILED',

      canonical:
        result ||
        null

    };

  }


  return {

    ready: true,

    written:
      result.written,

    blocked:
      result.blocked,

    protected:
      result.protected,

    count:
      result.count,

    source:
      'FIX_01C_CANONICAL_WRITER',

    canonical:
      result

  };

};


/* =========================================================================
   4. FIX MARKER
   ========================================================================= */

window.V26_FIX_01C_CANONICAL_WRITER =
  true;


console.log(
  'XSMN V2.6 FIX-01C — Canonical Persistence Writer ACTIVE'
);

/* =========================================================================
   XSMN V2.6 — FIX-01D
   SAFE LEGACY SHADOW STORAGE MIGRATION

   Strategy:
   1. Read canonical.
   2. Inspect known legacy keys.
   3. Merge without mutating source stores.
   4. Dedupe snapshots.
   5. Write through canonical writer only.
   6. Read-back verify.
   7. DO NOT delete legacy storage yet.
   ========================================================================= */

const SHADOW_LEGACY_KEYS_V26 = [

  'XSMN_SHADOW_SNAPSHOTS_V26',

  'SHADOW_SNAPSHOTS_V26',

  'shadowSnapshotsV26',

  'xsmm_shadow_v26'

];


/* =========================================================================
   1. EXTRACT SNAPSHOTS FROM LEGACY VALUE
   ========================================================================= */

function extractLegacyShadowSnapshotsV26(
  parsed
) {

  if (
    Array.isArray(
      parsed
    )
  ) {

    return parsed.slice();

  }


  if (
    parsed &&
    typeof parsed ===
      'object' &&
    Array.isArray(
      parsed.snapshots
    )
  ) {

    return parsed.snapshots.slice();

  }


  return null;

}


/* =========================================================================
   2. STABLE MIGRATION IDENTITY
   ========================================================================= */

function shadowMigrationIdentityV26(
  snapshot
) {

  if (
    !snapshot ||
    typeof snapshot !==
      'object'
  ) {

    return null;

  }


  /*
   * Ưu tiên identity mạnh nhất.
   */

  if (
    snapshot.snapshotKey
  ) {

    return (
      'KEY|' +
      String(
        snapshot.snapshotKey
      )
    );

  }


  if (
    snapshot.id
  ) {

    return (
      'ID|' +
      String(
        snapshot.id
      )
    );

  }


  /*
   * Fallback cho snapshot rất cũ.
   *
   * Không dùng Date.now().
   */

  return [

    'FALLBACK',

    snapshot.provinceSlug ||
      snapshot.province ||
      snapshot.slug ||
      '',

    snapshot.prize ||
      'db',

    snapshot.targetDrawKey ||
      '',

    snapshot.targetDrawDate ||
      snapshot.latestDrawDate ||
      '',

    snapshot.model ||
      '',

    snapshot.window != null
      ? String(
          snapshot.window
        )
      : '',

    snapshot.createdAt ||
      snapshot.generatedAt ||
      ''

  ].join('|');

}


/* =========================================================================
   3. SAFE MIGRATION
   ========================================================================= */

function migrateLegacyShadowStorageV26() {

  const canonical =
    readCanonicalShadowStoreV26();


  /*
   * Nếu canonical store đang corrupted,
   * tuyệt đối không migration/write.
   */

  if (
    !canonical ||
    canonical.ready !== true
  ) {

    const result = {

      ready: false,

      migrated: false,

      reason:
        canonical &&
        canonical.reason
          ? canonical.reason
          : 'CANONICAL_READ_FAILED',

      protected:
        true

    };


    window.LAST_V26_FIX_01D_MIGRATION =
      result;


    return result;

  }


  const canonicalRows =
    canonical.snapshots.slice();


  const merged =
    canonicalRows.slice();


  const identities =
    new Set();


  merged.forEach(
    snapshot => {

      const identity =
        shadowMigrationIdentityV26(
          snapshot
        );


      if (identity) {

        identities.add(
          identity
        );

      }

    }
  );


  const legacyReport =
    [];


  let legacyFound =
    0;

  let legacyRows =
    0;

  let imported =
    0;

  let duplicates =
    0;

  let invalid =
    0;


  for (
    const key of
    SHADOW_LEGACY_KEYS_V26
  ) {

    let raw =
      null;


    try {

      raw =
        localStorage.getItem(
          key
        );

    } catch (error) {

      legacyReport.push({

        key,

        ready: false,

        reason:
          'LEGACY_STORAGE_READ_ERROR',

        error:
          String(
            error.message ||
            error
          )

      });


      continue;

    }


    if (!raw) {

      legacyReport.push({

        key,

        ready: true,

        exists: false,

        rows: 0,

        imported: 0

      });


      continue;

    }


    legacyFound++;


    let parsed;


    try {

      parsed =
        JSON.parse(
          raw
        );

    } catch (error) {

      invalid++;


      legacyReport.push({

        key,

        ready: false,

        exists: true,

        reason:
          'LEGACY_JSON_INVALID'

      });


      /*
       * Không sửa / không xóa key lỗi.
       */

      continue;

    }


    const rows =
      extractLegacyShadowSnapshotsV26(
        parsed
      );


    if (
      !Array.isArray(
        rows
      )
    ) {

      invalid++;


      legacyReport.push({

        key,

        ready: false,

        exists: true,

        reason:
          'LEGACY_SCHEMA_UNKNOWN'

      });


      continue;

    }


    legacyRows +=
      rows.length;


    let importedFromKey =
      0;

    let duplicateFromKey =
      0;


    rows.forEach(
      snapshot => {

        if (
          !snapshot ||
          typeof snapshot !==
            'object'
        ) {

          invalid++;

          return;

        }


        const identity =
          shadowMigrationIdentityV26(
            snapshot
          );


        if (!identity) {

          invalid++;

          return;

        }


        if (
          identities.has(
            identity
          )
        ) {

          duplicates++;

          duplicateFromKey++;

          return;

        }


        merged.push(
          snapshot
        );


        identities.add(
          identity
        );


        imported++;

        importedFromKey++;

      }
    );


    legacyReport.push({

      key,

      ready: true,

      exists: true,

      rows:
        rows.length,

      imported:
        importedFromKey,

      duplicates:
        duplicateFromKey

    });

  }


  /*
   * Không có gì mới:
   * không cần write.
   */

  if (
    imported === 0
  ) {

    const result = {

      ready:
        invalid === 0,

      migrated: false,

      reason:
        invalid > 0
          ? 'LEGACY_STORE_REQUIRES_REVIEW'
          : 'NO_NEW_LEGACY_SNAPSHOTS',

      canonicalBefore:
        canonicalRows.length,

      canonicalAfter:
        canonicalRows.length,

      legacyFound,

      legacyRows,

      imported: 0,

      duplicates,

      invalid,

      legacyReport,

      destructive:
        false

    };


    window.LAST_V26_FIX_01D_MIGRATION =
      result;


    return result;

  }


  /*
   * -------------------------------------------------------------
   * WRITE THROUGH FIX-01C ONLY
   * -------------------------------------------------------------
   */

  const write =
    writeCanonicalShadowStoreV26(
      merged
    );


  if (
    !write ||
    write.ready !== true
  ) {

    const result = {

      ready: false,

      migrated: false,

      reason:
        write &&
        write.reason
          ? write.reason
          : 'CANONICAL_MIGRATION_WRITE_FAILED',

      canonicalBefore:
        canonicalRows.length,

      attemptedAfter:
        merged.length,

      imported,

      duplicates,

      invalid,

      legacyReport,

      destructive:
        false,

      write

    };


    window.LAST_V26_FIX_01D_MIGRATION =
      result;


    return result;

  }


  /*
   * -------------------------------------------------------------
   * READ-BACK VERIFY
   * -------------------------------------------------------------
   */

  const verify =
    readCanonicalShadowStoreV26();


  if (
    !verify ||
    verify.ready !== true
  ) {

    const result = {

      ready: false,

      migrated: true,

      verified: false,

      reason:
        'MIGRATION_READ_BACK_FAILED',

      imported,

      duplicates,

      invalid,

      legacyReport,

      destructive:
        false

    };


    window.LAST_V26_FIX_01D_MIGRATION =
      result;


    return result;

  }


  const verifiedIdentities =
    new Set(
      verify.snapshots
        .map(
          shadowMigrationIdentityV26
        )
        .filter(
          Boolean
        )
    );


  const expectedIdentities =
    merged
      .map(
        shadowMigrationIdentityV26
      )
      .filter(
        Boolean
      );


  const allPreserved =
    expectedIdentities.every(
      identity =>
        verifiedIdentities.has(
          identity
        )
    );


  const passed =
    (
      allPreserved &&
      verify.snapshots.length >=
        merged.length
    );


  const result = {

    ready:
      passed,

    migrated: true,

    verified:
      passed,

    reason:
      passed
        ? 'SAFE_LEGACY_MIGRATION_VERIFIED'
        : 'MIGRATION_INTEGRITY_CHECK_FAILED',

    canonicalBefore:
      canonicalRows.length,

    canonicalAfter:
      verify.snapshots.length,

    legacyFound,

    legacyRows,

    imported,

    duplicates,

    invalid,

    allPreserved,

    legacyReport,

    /*
     * FIX-01D không được delete legacy.
     */

    destructive:
      false,

    legacyRetired:
      false

  };


  window.LAST_V26_FIX_01D_MIGRATION =
    result;


  return result;

}


