/* =========================================================================
   XSMN V2.6 — FIX-01D EXECUTION
   SAFE LEGACY MIGRATION EXECUTION GATE

   Flow:
   1. Run PRE-MIGRATION GATE again.
   2. Capture canonical state before migration.
   3. Execute SAFE migration.
   4. Read canonical store again.
   5. Verify preservation / count.
   6. NEVER delete legacy storage.
   ========================================================================= */

function executeFix01DMigrationV26() {

  /*
   * -------------------------------------------------------------
   * STEP 1
   * PRE-MIGRATION GATE
   * -------------------------------------------------------------
   */

  const gate =
    testFix01DPreMigrationGateV26();


  if (
    !gate ||
    gate.ready !== true ||
    gate.allowed !== true
  ) {

    return {

      ready: false,

      executed: false,

      verified: false,

      reason:
        gate &&
        gate.reason
          ? gate.reason
          : 'PRE_MIGRATION_GATE_BLOCKED',

      gate

    };

  }


  /*
   * -------------------------------------------------------------
   * STEP 2
   * READ CANONICAL BEFORE
   * -------------------------------------------------------------
   */

  const before =
    readCanonicalShadowStoreV26();


  if (
    !before ||
    before.ready !== true ||
    !Array.isArray(
      before.snapshots
    )
  ) {

    return {

      ready: false,

      executed: false,

      verified: false,

      reason:
        'CANONICAL_BEFORE_NOT_READY'

    };

  }


  /*
   * RAM safety copy.
   *
   * Không phải persistent backup.
   * Chỉ dùng để kiểm tra preservation
   * trong execution hiện tại.
   */

  const beforeSnapshots =
    before.snapshots.slice();


  const beforeCount =
    beforeSnapshots.length;


  const beforeIds =
    beforeSnapshots
      .map(
        shadowMigrationIdentityV26
      )
      .filter(
        Boolean
      );


  /*
   * -------------------------------------------------------------
   * STEP 3
   * EXECUTE SAFE MIGRATION
   * -------------------------------------------------------------
   */

  const migration =
    migrateLegacyShadowStorageV26();


  if (
    !migration ||
    migration.ready !== true
  ) {

    const failure = {

      ready: false,

      executed: true,

      verified: false,

      reason:
        migration &&
        migration.reason
          ? migration.reason
          : 'MIGRATION_FAILED',

      beforeCount,

      migration

    };


    window.LAST_V26_FIX_01D_EXECUTION =
      failure;


    return failure;

  }


  /*
   * -------------------------------------------------------------
   * STEP 4
   * READ BACK CANONICAL
   * -------------------------------------------------------------
   */

  const after =
    readCanonicalShadowStoreV26();


  if (
    !after ||
    after.ready !== true ||
    !Array.isArray(
      after.snapshots
    )
  ) {

    const failure = {

      ready: false,

      executed: true,

      verified: false,

      reason:
        'CANONICAL_READ_BACK_FAILED',

      beforeCount,

      migration

    };


    window.LAST_V26_FIX_01D_EXECUTION =
      failure;


    return failure;

  }


  const afterCount =
    after.snapshots.length;


  const afterIds =
    new Set(
      after.snapshots
        .map(
          shadowMigrationIdentityV26
        )
        .filter(
          Boolean
        )
    );


  /*
   * -------------------------------------------------------------
   * STEP 5
   * VERIFY OLD CANONICAL RECORDS SURVIVED
   * -------------------------------------------------------------
   */

  const preserved =
    beforeIds.every(
      identity =>
        afterIds.has(
          identity
        )
    );


  if (!preserved) {

    const failure = {

      ready: false,

      executed: true,

      verified: false,

      reason:
        'PRE_EXISTING_CANONICAL_ROWS_LOST',

      beforeCount,

      afterCount,

      migration,

      legacyDeleted:
        false

    };


    window.LAST_V26_FIX_01D_EXECUTION =
      failure;


    return failure;

  }


  /*
   * Canonical count tuyệt đối
   * không được nhỏ hơn trước migration.
   */

  if (
    afterCount <
    beforeCount
  ) {

    const failure = {

      ready: false,

      executed: true,

      verified: false,

      reason:
        'CANONICAL_COUNT_DECREASED',

      beforeCount,

      afterCount,

      migration,

      legacyDeleted:
        false

    };


    window.LAST_V26_FIX_01D_EXECUTION =
      failure;


    return failure;

  }


  /*
   * -------------------------------------------------------------
   * STEP 6
   * SUCCESS
   * -------------------------------------------------------------
   */

  const result = {

    ready: true,

    executed: true,

    verified: true,

    reason:
      'FIX_01D_EXECUTION_PASS',

    beforeCount,

    afterCount,

    added:
      afterCount -
      beforeCount,

    migrationImported:
      migration.imported != null
        ? migration.imported
        : 0,

    migrationDuplicates:
      migration.duplicates != null
        ? migration.duplicates
        : 0,

    migrationInvalid:
      migration.invalid != null
        ? migration.invalid
        : 0,

    preserved,

    /*
     * CỰC KỲ QUAN TRỌNG:
     * FIX-01D không retirement.
     */

    legacyDeleted:
      false,

    migration

  };


  window.LAST_V26_FIX_01D_EXECUTION =
    result;


  return result;

}


