/* =========================================================================
   XSMN V2.6 — FIX-01D
   POST-MIGRATION INTEGRITY CHECK

   READ ONLY.

   Mục tiêu:
   - Kiểm tra Canonical Store sau migration.
   - Kiểm tra duplicate identity.
   - Kiểm tra snapshot structure.
   - Kiểm tra legacy vẫn còn.
   - Kiểm tra kết quả execution trước.
   - KHÔNG write.
   - KHÔNG migrate.
   - KHÔNG delete legacy.
   ========================================================================= */

function checkFix01DPostMigrationIntegrityV26() {

  /*
   * FIX-01D POST-MIGRATION CHECK
   *
   * Persistent-only capable.
   * READ ONLY.
   *
   * Không yêu cầu execution RAM
   * tồn tại sau reload.
   */

  const execution =
    window.LAST_V26_FIX_01D_EXECUTION ||
    null;


  const executionAvailable =
    Boolean(
      execution &&
      execution.verified === true
    );


  /*
   * -------------------------------------------------------------
   * READ CANONICAL SOURCE OF TRUTH
   * -------------------------------------------------------------
   */

  let canonical;


  try {

    canonical =
      readCanonicalShadowStoreV26();

  } catch (error) {

    return {

      ready: false,

      passed: false,

      reason:
        'CANONICAL_READ_EXCEPTION',

      error:
        String(
          error.message ||
          error
        )

    };

  }


  if (
    !canonical ||
    canonical.ready !== true ||
    !Array.isArray(
      canonical.snapshots
    )
  ) {

    return {

      ready: false,

      passed: false,

      reason:
        'CANONICAL_STORE_NOT_READY',

      canonical

    };

  }


  const snapshots =
    canonical.snapshots;


  const canonicalCount =
    snapshots.length;


  /*
   * -------------------------------------------------------------
   * COUNT
   * -------------------------------------------------------------
   */

  const expectedCount =
    executionAvailable &&
    execution.afterCount != null

      ? execution.afterCount

      : canonicalCount;


  const countMatch =
    canonicalCount ===
    expectedCount;


  /*
   * -------------------------------------------------------------
   * IDENTITY
   * -------------------------------------------------------------
   */

  const identities =
    snapshots.map(
      snapshot => {

        try {

          return shadowMigrationIdentityV26(
            snapshot
          );

        } catch (error) {

          return null;

        }

      }
    );


  const validIdentities =
    identities.filter(
      Boolean
    );


  const identitySet =
    new Set(
      validIdentities
    );


  const invalidIdentityCount =
    identities.length -
    validIdentities.length;


  const duplicateCount =
    validIdentities.length -
    identitySet.size;


  /*
   * -------------------------------------------------------------
   * SNAPSHOT STRUCTURE
   * -------------------------------------------------------------
   */

  let invalidSnapshotCount =
    0;


  snapshots.forEach(
    snapshot => {

      if (
        !snapshot ||
        typeof snapshot !==
          'object'
      ) {

        invalidSnapshotCount++;

        return;

      }


      const province =
        snapshot.province ||
        snapshot.provinceSlug ||
        snapshot.slug ||
        null;


      const status =
        snapshot.status ||
        (
          snapshot.verification &&
          snapshot.verification.status
        ) ||
        null;


      if (
        !province ||
        !status
      ) {

        invalidSnapshotCount++;

      }

    }
  );


  /*
   * -------------------------------------------------------------
   * LEGACY ROLLBACK SOURCE
   * -------------------------------------------------------------
   */

  const legacyKeys =
  typeof SHADOW_LEGACY_KEYS_V26 !==
      'undefined' &&
    Array.isArray(
      SHADOW_LEGACY_KEYS_V26
    )

    ? SHADOW_LEGACY_KEYS_V26

    : [];


  const legacyExistingKeys =
    legacyKeys.filter(
      key => {

        try {

          return (
            localStorage.getItem(
              key
            ) !== null
          );

        } catch (error) {

          return false;

        }

      }
    );


  const legacyExisting =
    legacyExistingKeys.length;


  /*
   * -------------------------------------------------------------
   * PRESERVATION
   * -------------------------------------------------------------
   */

  const preservationPass =
    executionAvailable
      ? execution.preserved === true
      : true;


  const noUnexpectedShrink =
    executionAvailable

      ? (
          execution.beforeCount == null ||
          canonicalCount >=
            execution.beforeCount
        )

      : true;


  /*
   * -------------------------------------------------------------
   * FINAL INTEGRITY
   * -------------------------------------------------------------
   */

  const passed =

    canonicalCount > 0 &&

    countMatch &&

    invalidIdentityCount === 0 &&

    duplicateCount === 0 &&

    invalidSnapshotCount === 0 &&

    preservationPass &&

    noUnexpectedShrink &&

    legacyExisting > 0;


  let reason =
    'POST_MIGRATION_INTEGRITY_PASS';


  if (
    canonicalCount <= 0
  ) {

    reason =
      'CANONICAL_EMPTY';

  } else if (
    !countMatch
  ) {

    reason =
      'CANONICAL_COUNT_MISMATCH';

  } else if (
    invalidIdentityCount > 0
  ) {

    reason =
      'INVALID_CANONICAL_IDENTITY';

  } else if (
    duplicateCount > 0
  ) {

    reason =
      'CANONICAL_DUPLICATE_IDENTITY';

  } else if (
    invalidSnapshotCount > 0
  ) {

    reason =
      'INVALID_CANONICAL_SNAPSHOT';

  } else if (
    !preservationPass
  ) {

    reason =
      'CANONICAL_PRESERVATION_FAILED';

  } else if (
    !noUnexpectedShrink
  ) {

    reason =
      'CANONICAL_UNEXPECTED_SHRINK';

  } else if (
    legacyExisting === 0
  ) {

    reason =
      'LEGACY_ROLLBACK_SOURCE_MISSING';

  }


  const result = {

    ready: true,

    passed,

    reason,

    version:
      'V2.6',

    fix:
      'FIX-01D',

    mode:
      'POST_MIGRATION_INTEGRITY',

    readOnly:
      true,

    executionEvidence:
      executionAvailable
        ? 'RAM + PERSISTENT'
        : 'PERSISTENT_ONLY',

    canonicalCount,

    expectedCount,

    countMatch,

    invalidIdentityCount,

    duplicateCount,

    invalidSnapshotCount,

    preservationPass,

    noUnexpectedShrink,

    legacyKeysChecked:
      legacyKeys.length,

    legacyExisting,

    legacyExistingKeys,

    legacyDeleted:
      legacyExisting === 0

  };


  window.LAST_V26_FIX_01D_POST_CHECK =
    result;


  return result;

}


